        try (DatagramSocket socket = new DatagramSocket())
        {

            socket.connect(InetAddress.getByName("8.8.8.8"), 1366);

            var ipAddress = socket.getLocalAddress().getHostAddress();

            if (ipAddress != null && !ipAddress.isEmpty() && (ipAddress.equalsIgnoreCase("172.16.8.158") || ipAddress.equalsIgnoreCase("172.16.8.156")))
