            var event = message.body();

            var result = new JsonArray();

            var futures = new ArrayList<Future<Void>>();

            event.put(EventBusConstants.EVENT_TYPE, EventBusConstants.UI_ACTION_TRACE_SERVICE_HIERARCHY_FETCH)
                    .put(AIOpsConstants.DEPENDENCY_TYPE, AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName());

            for (var dependencyFormat : dependencyFormats)
            {
                var future = Promise.<Void>promise();

