                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                            .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, exception.getMessage()));

                    future.complete();
                }
            }

            Future.join(futures).onComplete(handler ->
            {
                if (MotadataConfigUtil.devMode())
                {
                    message.reply(event.put(RESULT, result.stream().distinct().collect(JsonArray::new, JsonArray::add, JsonArray::addAll)));
