public class TestLogStatCalculator
{
    private static MessageConsumer<byte[]> messageConsumer;

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    public void testLogStat(VertxTestContext testContext) throws InterruptedException
    {

        messageConsumer = Bootstrap.vertx().eventBus().localConsumer(EventBusConstants.EVENT_DATASTORE_WRITE + "." + DatastoreConstants.DatastoreCategory.EVENT.getName(), message ->
        {

            var result = TestUtil.decodeEventBufferSingleRow(Buffer.buffer(message.body()));

            if (result.getString(PLUGIN_ID).equalsIgnoreCase(DatastoreConstants.PluginId.LOG_EVENT_STAT.getName() + "-log.stat"))
            {
                Assertions.assertEquals("8.8.8.8", result.getString("source"));

                Assertions.assertEquals(400, result.getLong(LOG_VOLUME_BYTES));

                Assertions.assertEquals(0, result.getLong(LOGS_PER_SEC));

                Assertions.assertEquals(40, result.getLong(LOG_VOLUME_BYTES_PER_SEC));

                messageConsumer.unregister();

                testContext.completeNow();
            }
        });

        var stats = new HashMap<String, long[]>();

        stats.put("8.8.8.8" + SEPARATOR + "linux.audit" + SEPARATOR + "linux", new long[]{1, 200});

        for (var index = 0; index < MotadataConfigUtil.getLogParsers(); index++)
        {
            Bootstrap.vertx().eventBus().send(EVENT_LOG_STAT, stats);
        }

        Assertions.assertTrue(testContext.awaitCompletion(20, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }
