import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_TYPE;
import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID;
import static com.mindarray.eventbus.EventBusConstants.*;

public class MetricAgentEventProcessor extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(MetricAgentEventProcessor.class, MOTADATA_AGENT, "Metric Agent Event Processor");
    private final AtomicBoolean done = new AtomicBoolean(false);
    private EventEngine eventEngine;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {

        eventEngine = new EventEngine().setLogger(LOGGER).setEventType(EventBusConstants.EVENT_METRIC_AGENT).setPersistEventOffset(true)
                .setEventHandler(event ->
                {
                    try
                    {
                        var object = AgentConfigStore.getStore().getAgentId(event.getString(Agent.AGENT_UUID)) != null
                                ? ObjectConfigStore.getStore().getItemByAgentId(AgentConfigStore.getStore().getAgentId(event.getString(Agent.AGENT_UUID))) : null;

                        if (object != null)
                        {
                            event.mergeIn(object);

                            var context = new JsonObject(event.getString(EventBusConstants.EVENT_CONTEXT));

                            event.remove(EventBusConstants.EVENT_CONTEXT);

                            event.put(EVENT_TIMESTAMP, context.remove(EVENT_TIMESTAMP));

                            event.put(RESULT, context);

                            var objectType = event.getString(AIOpsObject.OBJECT_TYPE);

                            context.stream().takeWhile(entry -> !done.get()).forEach(entry ->
                            {
                                try
                                {
                                    if (!entry.getKey().equalsIgnoreCase(NMSConstants.CORRELATION_METRICS))
                                    {
                                        if (entry.getValue() instanceof JsonArray || entry.getValue() instanceof List)
                                        {
                                            var type = NMSConstants.Type.valueOfName(entry.getKey());

                                            var plugin = switch (type)
                                            {
                                                case SYSTEM_PROCESS, SYSTEM_PROCESS_NETWORK_CONNECTION ->
                                                        objectType.equalsIgnoreCase(NMSConstants.Type.WINDOWS.getName()) ? NMSConstants.MetricPlugin.WINDOWS_PROCESS.getName() :
                                                                NMSConstants.MetricPlugin.LINUX_PROCESS.getName();

                                                case SYSTEM_DISK_VOLUME ->
                                                        objectType.equalsIgnoreCase(NMSConstants.Type.WINDOWS.getName()) ? NMSConstants.MetricPlugin.WINDOWS_DISK.getName() :
                                                                NMSConstants.MetricPlugin.LINUX_DISK.getName();

                                                case SYSTEM_CPU_CORE ->
                                                        objectType.equalsIgnoreCase(NMSConstants.Type.WINDOWS.getName()) ? NMSConstants.MetricPlugin.WINDOWS_CPU_CORE.getName() :
                                                                NMSConstants.MetricPlugin.LINUX_CPU_CORE.getName();

                                                case SYSTEM_SERVICE ->
                                                        NMSConstants.MetricPlugin.WINDOWS_SERVICE.getName();

                                                case SYSTEM_NETWORK_INTERFACE ->
                                                        objectType.equalsIgnoreCase(NMSConstants.Type.WINDOWS.getName()) ? NMSConstants.MetricPlugin.WINDOWS_NETWORK_INTERFACE.getName() :
                                                                NMSConstants.MetricPlugin.LINUX_NETWORK_INTERFACE.getName();

                                                default -> EMPTY_VALUE;
                                            };

                                            if (CommonUtil.isNotNullOrEmpty(plugin))
                                            {
                                                event.mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin(plugin));

                                                event.put(Metric.METRIC_CATEGORY, NMSConstants.getCategory(NMSConstants.Type.valueOfName(objectType)).getName());

                                                event.put(Metric.METRIC_OBJECT, event.getLong(ID));

                                                done.set(true);
                                            }
                                        }

                                        else
                                        {
                                            event.mergeIn(ObjectManagerCacheStore.getStore().getItemByMetricPlugin(objectType.equalsIgnoreCase(NMSConstants.Type.WINDOWS.getName()) ? NMSConstants.MetricPlugin.WINDOWS.getName() :
                                                    NMSConstants.MetricPlugin.LINUX.getName()));

                                            event.put(Metric.METRIC_CATEGORY, NMSConstants.getCategory(NMSConstants.Type.valueOfName(objectType)).getName());

                                            event.put(Metric.METRIC_OBJECT, event.getLong(ID));

                                            done.set(true);
                                        }
                                    }
                                }
                                catch (Exception exception)
                                {
                                    LOGGER.error(exception);
                                }
                            });

                            if (done.get())
                            {
                                vertx.eventBus().send("agent.health.statistics", event);

                                event.mergeIn(JsonObject.mapFrom(event.remove(Metric.METRIC_CONTEXT)));

                                vertx.eventBus().send(EventBusConstants.EVENT_METRIC_ENRICHER, event);

                                done.set(false);
                            }

                            if (CommonUtil.traceEnabled())
                            {
                                LOGGER.trace(String.format("agent poll response: %s", CommonUtil.removeSensitiveFields(event, false).encodePrettily()));
                            }
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }

                }).start(vertx, promise);
    }

    private void enrich(JsonObject context, JsonObject event)
    {
        try
        {
            if (RemoteEventProcessorConfigStore.getStore().getItemIdByUUID(event.getString(Agent.AGENT_UUID)) != null
                    && (context.containsKey("system.disk.used.percent")))
            {
                var usedDiskPercent = context.getDouble("system.disk.used.percent");

                var severity = Severity.CLEAR;

                if (usedDiskPercent >= 95)
                {
                    // critical
                    severity = Severity.CRITICAL;

                    var type = RemoteEventProcessorConfigStore.getStore().getItemByValue(REMOTE_EVENT_PROCESSOR_UUID, event.getString(Agent.AGENT_UUID)).getString(REMOTE_EVENT_PROCESSOR_TYPE);

                    LOGGER.info(String.format("Disk Utilization is critical with value %s for type %s", context.getDouble("system.disk.used.percent"), type));

                    switch (GlobalConstants.BootstrapType.valueOf(type))
                    {
                        case DEFAULT, MASTER, SLAVE ->
                        {
                            LOGGER.warn("stopping Motadata App...");

                            Bootstrap.undeployLicensedVerticle().onComplete(handler ->
                            {
                                LOGGER.warn("motadata engine stopped due to disk utilization...");

                                BootstrapMain.APP_SERVER_ONLINE.set(false);

                            });
                        }

                        case COLLECTOR ->
                        {
                            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_PUBLICATION_MOTADATA_MANAGER, new JsonObject().put(EventBusConstants.EVENT_TOPIC, MOTADATA_MANAGER_TOPIC).put(EVENT_TYPE, EventBusConstants.EVENT_REMOTE_PROCESSOR_STOP)
                                    .put(REMOTE_EVENT_PROCESSOR_UUID, event.getString(Agent.AGENT_UUID)));

                            LOGGER.warn(String.format("shutdown command sent to remote event processor %s", event.getString(Agent.AGENT_UUID)));


                        }

                        case PRIMARY, SECONDARY ->
                        {
                            Bootstrap.vertx().eventBus().send(EventBusConstants.EVENT_PUBLICATION_MOTADATA_MANAGER, new JsonObject().put(EventBusConstants.EVENT_TOPIC, MOTADATA_MANAGER_TOPIC).put(EVENT_TYPE, EventBusConstants.EVENT_REMOTE_PROCESSOR_STOP)
                                    .put("datastore.uuid", event.getString(Agent.AGENT_UUID)));

                            LOGGER.warn(String.format("shutdown command sent to data node %s", event.getString(Agent.AGENT_UUID)));
                        }
                    }
                }
                else if (usedDiskPercent >= 90)
                {
                    // major
                    severity = Severity.MAJOR;

                    var type = RemoteEventProcessorConfigStore.getStore().getItemByValue(REMOTE_EVENT_PROCESSOR_UUID, event.getString(Agent.AGENT_UUID)).getString(REMOTE_EVENT_PROCESSOR_TYPE);

                    LOGGER.warn(String.format("Disk Utilization is major with value %f for type %s", usedDiskPercent, type));
                }
                else if (usedDiskPercent >= 85)
                {
                    // warning
                    severity = Severity.WARNING;

                    var type = RemoteEventProcessorConfigStore.getStore().getItemByValue(REMOTE_EVENT_PROCESSOR_UUID, event.getString(Agent.AGENT_UUID)).getString(REMOTE_EVENT_PROCESSOR_TYPE);

                    LOGGER.info(String.format("Disk Utilization is warning with value %f for type %s", usedDiskPercent, type));
                }

                if (severity != Severity.CLEAR)
                {
                    var user = UserConfigStore.getStore().getItem(DEFAULT_ID, false);

                    if (user.containsKey(User.USER_EMAIL) && user.getString(User.USER_EMAIL) != null)
                    {
                        Notification.sendEmail(new JsonObject()
                                .put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_DISPOSITION_TYPE, "inline").put(Notification.EMAIL_NOTIFICATION_ATTACHMENT_TYPE, "image/png")
                                .put(Notification.EMAIL_NOTIFICATION_ATTACHMENTS, new JsonArray().add(severity.name().toLowerCase() + ".png").addAll(Notification.EMAIL_NOTIFICATION_INLINE_ATTACHMENT_ICONS))
                                .put(Notification.EMAIL_NOTIFICATION_SUBJECT, String.format("System Disk Utilization reached %s level.", severity.name()))
                                .put(Notification.EMAIL_NOTIFICATION_RECIPIENTS, new JsonArray().add(user.getString(User.USER_EMAIL)))
                                .put(Notification.EMAIL_NOTIFICATION_CONTENT, new StringSubstitutor(new JsonObject().put(SEVERITY, severity).put(AIOpsObject.OBJECT_NAME, event.getString(AIOpsObject.OBJECT_NAME)).put(METRIC, "system.disk.used.percent").put(TIME_STAMP, event.getLong(EVENT_TIMESTAMP)).put(AIOpsObject.OBJECT_TARGET, event.getString(AIOpsObject.OBJECT_TARGET)).put(AIOpsObject.OBJECT_TYPE, event.getString(AIOpsObject.OBJECT_TYPE)).put(VALUE, context.getDouble("system.disk.used.percent")).put(MESSAGE, "Disk Utilization is beyond threshold").getMap())
                                        .replace(Notification.EMAIL_NOTIFICATION_DISK_UTILIZATION_TEMPLATE).getBytes(StandardCharsets.UTF_8)));

                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

    }

    @Override
    public void stop(Promise<Void> promise)
    {
        eventEngine.stop(vertx, promise);
    }
}

