            if (category == NMSConstants.Category.NETWORK)
            {
                return configs.containsKey("config.request.timeout.seconds") ? Math.max(60, Math.min(configs.getInteger("config.request.timeout.seconds"), 300)) : 60;

            }
            else
            {
                return 60;
