                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                }
                            });

                    case UPSERT -> Bootstrap.configDBService().upsert(collection,context.getJsonObject(DB_QUERY),context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0),SYSTEM_USER,SYSTEM_REMOTE_ADDRESS,false,result ->
                    {
