@TestMethodOrder(MethodOrderer.OrderAnnotation.class)
@Timeout(30 * 1000)
@EnabledIfSystemProperty(named = "test.mode", matches = "^APP|^PRIMARY$")
public class TestFlowStatCalculator
{
    private static final Logger LOGGER = new Logger(TestFlowStatCalculator.class, "Stat", "Test Flow Stat Calculator");
    private static MessageConsumer<byte[]> eventMessageConsumer;
    private static MessageConsumer<JsonObject> metricMessageConsumer;

    @RepeatedIfExceptionsTest(suspend = 3000L)
    @Order(1)
    public void testFlowStatCalculator(VertxTestContext testContext) throws InterruptedException
    {

        var id = TestUtil.vertx().setPeriodic(2 * 1000, timer -> TestUtil.vertx().eventBus().publish(EVENT_DATASTORE_PING, new JsonObject().put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, "primary_db_uuid_for_datastore").put(STATUS, STATUS_UP)));

        var futures = new ArrayList<Future<Void>>();

        var metricPromise = Promise.<Void>promise();

        futures.add(metricPromise.future());

        metricMessageConsumer = TestUtil.vertx().eventBus().localConsumer("test.datastore.metric", message ->
        {
            LOGGER.info("Message received.... " + message.body().encodePrettily());

            var result = TestUtil.decodeMetricEnricherBuffer(message.body());

            LOGGER.info(DateTimeUtil.timestamp() + ": RESULT: " + result.encodePrettily());

            if (result.getString(PLUGIN_ID).equalsIgnoreCase(DatastoreConstants.PluginId.FLOW_STAT.getName() + DASH_SEPARATOR + "flow.stat.calculator"))
            {
                LOGGER.info("Datastore type: Metric, event received : " + result);

                Assertions.assertEquals(NMSConstants.DUMMY_OBJECT_ID, result.getInteger(AIOpsObject.OBJECT_ID));

                Assertions.assertTrue(0L <= result.getLong(FLOW_VOLUME_BYTES));

                Assertions.assertTrue(0L <= result.getLong(FLOWS_TOTAL));

                Assertions.assertTrue(0L <= result.getLong(FLOWS_PER_SEC));

                Assertions.assertTrue(0L <= result.getLong(FLOW_VOLUME_BYTES_PER_SEC));

                metricMessageConsumer.unregister();

                metricPromise.complete();

            }});

        var eventPromise = Promise.<Void>promise();

        futures.add(eventPromise.future());

        eventMessageConsumer = Bootstrap.vertx().eventBus().localConsumer(EVENT_DATASTORE_WRITE + "." + DatastoreConstants.DatastoreCategory.EVENT.getName(), message ->
        {
            var result = TestUtil.decodeEventBufferSingleRow(Buffer.buffer(message.body()));

            if (result.getString(PLUGIN_ID).equalsIgnoreCase(DatastoreConstants.PluginId.FLOW_VOLUME_STAT.getName() + DASH_SEPARATOR + "flow.volume.stat"))
            {
                LOGGER.info("Datastore type: Log, event received : " + result);

                Assertions.assertTrue(0L <= result.getLong(FlowEngineConstants.SOURCE_FLOW_VOLUME_BYTES));

                Assertions.assertTrue(0L <= result.getLong(FlowEngineConstants.SOURCE_FLOWS));

                eventMessageConsumer.unregister();

                eventPromise.complete();
            }
        });

        for (var index = 0; index < MotadataConfigUtil.getLogParsers(); index++)
        {
            Bootstrap.vertx().eventBus().send(EVENT_FLOW_PROCESSOR_STAT, new JsonObject()
                    .put(RESULT, new JsonObject().put("8.8.8.8", new JsonArray().add(1).add(200)))
                    .put(AGGREGATED_FLOWS, 1)
                    .put(AGGREGATED_VOLUME_BYTES, 200));

            Bootstrap.vertx().eventBus().send(EVENT_FLOW_REMOTE_STAT, new JsonObject()
                    .put(TOTAL_FLOWS, 3000));
        }

        Future.join(futures).onComplete(handler ->{

            if(handler.succeeded())
            {
                TestUtil.vertx().cancelTimer(id);

                testContext.completeNow();
            }
        });

        Assertions.assertTrue(testContext.awaitCompletion(100, TimeUnit.SECONDS), "could not complete the task, reason: timed out.");
    }
}

