                    .add(new JsonObject().put(DATA_POINT, SLO_INSTANCE_DURATION).put(AGGREGATOR, EMPTY_VALUE).put(ENTITY_TYPE, APIConstants.Entity.OBJECT.getName()).put(ENTITIES, SLO_ENTITIES)));

    // visualization data source context
    private static final JsonArray VISUALIZATION_DATA_SOURCE = new JsonArray();

    // timeline context
    private static final JsonObject TIMELINE = new JsonObject()
            .put(RELATIVE_TIMELINE, VisualizationTimeline.CUSTOM.getName())
            .put(VISUALIZATION_TIME_RANGE_INCLUSIVE, NO)
            .put(FROM_TIME, "00:00:00")
            .put(TO_TIME, "00:00:10");

    // main query context
    private static final JsonObject QUERY = new JsonObject()
            .put(ID, NOT_AVAILABLE)
            .put(EVENT_TYPE, EVENT_SLO_FLAP_QUERY_RESPONSE)
            .put(VISUALIZATION_TIMELINE_PREFERENCE, NO)
            .put(VISUALIZATION_TIMELINE, TIMELINE)
            .put(VISUALIZATION_CATEGORY, VisualizationCategory.HISTOGRAM.getName())
            .put(VISUALIZATION_TYPE, "Area")
            .put(VISUALIZATION_RESULT_BY, new JsonArray())
            .put(VISUALIZATION_DATA_SOURCES, VISUALIZATION_DATA_SOURCE)
            .put(User.USER_NAME, DEFAULT_USER);

    // ------------------------ Verticle related methods ------------------------ //
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        LOGGER.info("SLO Corrector started...");

        mappers = new HashSet<>();

        vertx.eventBus().<JsonObject>localConsumer(EVENT_SLO_CORRECT, message -> executeQuery(message.body()));

        vertx.eventBus().<JsonObject>localConsumer(EVENT_SLO_FLAP_QUERY_RESPONSE, message ->
        {
            try
            {
                var response = message.body();

                if (response.getInteger(VisualizationConstants.QUERY_PROGRESS) >= 100)
                {
                    if (CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Received response: " + response.encode());
                    }

                    var result = VisualizationConstants.unpack(message.body().getBuffer(RESULT), LOGGER, false, message.body(), true, true);

                    if (CommonUtil.traceEnabled())
                    {
                        LOGGER.trace("Unpacked response: " + result.encode());
                    }

                    if (result.containsKey(RESULT) && !result.getJsonArray(RESULT).isEmpty())
                    {
                        process(result.getJsonArray(RESULT), response.getLong(SLOCycle.SLO_CYCLE_ID, -1L), response.getJsonArray(CorrectionProfile.CORRECTION_PROFILE_IDS, null), response.getJsonArray(ENTITIES));
                    }
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        promise.complete();
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        LOGGER.info("SLO Corrector undeployed...");

        promise.complete();
    }


    // ------------------------ DB Query related methods ------------------------ //

    /**
     * Here we receive the cycle id on which we've to apply the correction and the correction profile id.
     * This method mainly builds the query and executes it.
     * @param event: correction event received from UI
     */
    private void executeQuery(JsonObject event)
    {
        try
        {
            var cycleId = event.getLong(SLOCycle.SLO_CYCLE_ID);

            var sloCycle = SLOCycleConfigStore.getStore().getItem(cycleId);

            var sloId = sloCycle.getLong(SLOProfile.SLO_PROFILE_ID);

            var sloProfile = SLOProfileConfigStore.getStore().getItem(sloId);

            var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

            // build the timeline
            TIMELINE.put(FROM_DATE, DateTimeUtil.secondsToTimestamp(DATE_FORMAT, sloCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME), EMPTY_VALUE))
                    .put(TO_DATE, DateTimeUtil.secondsToTimestamp(DATE_FORMAT, sloCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME), EMPTY_VALUE));

            SLO_ENTITIES.clear();

            SLO_ENTITIES.addAll(sloCycle.getJsonArray(ENTITIES));

            if (sloContext.getString(SLOProfile.SLO_INSTANCE).equalsIgnoreCase(NMSConstants.InstanceType.MONITOR.getName()))
            {
                VISUALIZATION_DATA_SOURCE.clear();

                VISUALIZATION_DATA_SOURCE.add(SLO_OBJECT_FLAP_DATASOURCE);
            }
            else
            {
                VISUALIZATION_DATA_SOURCE.clear();

                VISUALIZATION_DATA_SOURCE.add(SLO_INSTANCE_FLAP_DATASOURCE);
            }

            if (CommonUtil.traceEnabled())
            {
                LOGGER.trace("Executing query: " + QUERY.encode());
            }

            // send the query
            vertx.eventBus().send(EVENT_VISUALIZATION, QUERY
                    .put("store.suffix", sloId + GROUP_SEPARATOR + cycleId)
                    .put(ENTITIES, event.getJsonArray(ENTITIES))
                    .put(SLOCycle.SLO_CYCLE_ID, cycleId)
                    .put(CorrectionProfile.CORRECTION_PROFILE_IDS, event.getJsonArray(CorrectionProfile.CORRECTION_PROFILE_IDS)));

            if (MotadataConfigUtil.devMode())
            {
                vertx.eventBus().send("slo.query.test", QUERY);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ Result Processing related methods ------------------------ //

    private void process(JsonArray result, long cycleId, JsonArray correctionProfileIds, JsonArray entities)
    {
        try
        {
            // cycleId and correctionProfileId must be there in the event
            if (cycleId != NOT_AVAILABLE && correctionProfileIds != null)
            {
                var sloCycle = SLOCycleConfigStore.getStore().getItem(cycleId);

                // get the correction timestamps that can be applied to current cycle
                var correctionTimestamps = SLOConstants.getCorrectionTimestamps(sloCycle, CorrectionProfileConfigStore.getStore().getItems(correctionProfileIds));

                if (!correctionTimestamps.isEmpty())
                {
                    LOGGER.info("correction timestamps: " + new JsonArray(correctionTimestamps));

                    // build the tree map of events using the result
                    var sloEvents = processResult(result);

                    if (!sloEvents.isEmpty())
                    {
                        LOGGER.info("result processed successfully applying correction...");

                        // apply the correction
                        correct(sloEvents, correctionTimestamps, entities);

                        LOGGER.info("correction applied successfully, generating new cycle...");

                        if (CommonUtil.traceEnabled())
                        {
                            LOGGER.trace("corrected slo statuses: " + sloEvents);
                        }

                        var correctedCycle = sloCycle.copy()
                                .put(ID, SLOCycleConfigStore.getStore().newId())
                                .put(SLOCycle.SLO_CYCLE_NAME, sloCycle.getString(SLOCycle.SLO_CYCLE_NAME) + " (Corrected) - " + DateTimeUtil.getScheduledTimestamp(System.currentTimeMillis()));

                        if (correctedCycle.getJsonArray(CorrectionProfile.CORRECTION_PROFILE_IDS) != null)
                        {
                            correctedCycle.getJsonArray(CorrectionProfile.CORRECTION_PROFILE_IDS).addAll(correctionProfileIds);
                        }
                        else
                        {
                            correctedCycle.put(CorrectionProfile.CORRECTION_PROFILE_IDS, correctionProfileIds);
                        }

                        Bootstrap.configDBService().save(DBConstants.TBL_SLO_CYCLE, correctedCycle, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, future ->
                        {
                           if (future.succeeded())
                           {
                               SLOCycleConfigStore.getStore().addItem(future.result()).onComplete(asyncResult->
                               {
                                   if (asyncResult.succeeded())
                                   {
                                       LOGGER.info("new corrected cycle created successfully");

                                       // recalculate the SLO
                                       recalculate(future.result(), sloEvents);
                                   }
                                   else
                                   {
                                       LOGGER.error(asyncResult.cause());
                                   }
                               });
                           }
                           else
                           {
                               LOGGER.error(future.cause());
                           }
                        });
                    }
                    else
                    {
                        LOGGER.warn("failed to process result");
                    }
                }
                else
                {
                    LOGGER.warn(String.format(ErrorMessageConstants.NO_CORRECTION_TIMELINE_QUALIFIED, sloCycle.getString(SLOCycle.SLO_CYCLE_NAME)));
                }
            }
            else
            {
                LOGGER.warn("cycle id or correction profile id not found in the event");
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private Map<String, TreeMap<Long, Integer>> processResult(JsonArray result)
    {
        var sloStatuses = new HashMap<String, TreeMap<Long, Integer>>();

        for (var index = 0; index < result.size(); index++)
        {
            var entry = result.getJsonObject(index);

            var id = ArchivedObjectConfigStore.getStore().getIdByObjectId(CommonUtil.getInteger(entry.getString(AIOpsObject.OBJECT_ID)));

            var instance = entry.containsKey(SLO_INSTANCE) && !entry.getString(SLO_INSTANCE).isEmpty();

            var key = instance ? id + INSTANCE_SEPARATOR + entry.getString(SLO_INSTANCE) : CommonUtil.getString(id);

            sloStatuses.computeIfAbsent(key, value -> new TreeMap<>()).put(entry.getLong(TIMESTAMP) / 1000,
                    entry.getInteger((instance ? SLO_INSTANCE_STATUS_FLAP : SLO_OBJECT_STATUS_FLAP) + CARET_SEPARATOR + VALUE));
        }

        return sloStatuses;
    }

    // ------------------------ Recalculation related methods ------------------------ //

    private void recalculate(long correctedCycleId, Map<String, TreeMap<Long, Integer>> sloEvents)
    {
        try
        {
            var correctedSLOCycle = SLOCycleConfigStore.getStore().getItem(correctedCycleId);

            var endTime = correctedSLOCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME);

            var startTime = correctedSLOCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME);

            var sloId = correctedSLOCycle.getLong(SLOProfile.SLO_PROFILE_ID);

            // send notification to db
            VisualizationConstants.sendCycleStartNotification(sloId.toString(), correctedCycleId, startTime, LOGGER);

            var sloProfile = SLOProfileConfigStore.getStore().getItem(sloId);

            var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

            var availability = sloProfile.getString(SLOProfile.SLO_PROFILE_TYPE, EMPTY_VALUE).equalsIgnoreCase(SLOType.AVAILABILITY.getName());

            var duration = correctedSLOCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME) - correctedSLOCycle.getLong(SLOCycle.SLO_CYCLE_START_TIME);

            // start calculating
            var events = new TreeMap<Long, Integer>();

            // add initial entry to get the global SLO data from the startTime itself
            events.put(startTime, 0);

            // calculate instance SLO
            for (var entry : sloEvents.entrySet())
            {
                var data = new JsonObject().put(DURATION_LEFT, duration);

                var tokens = entry.getKey().split(INSTANCE_SEPARATOR);

                var objectId = CommonUtil.getLong(tokens[0]);

                var instance = tokens.length > 1 ? tokens[1] : EMPTY_VALUE;

                for (var event : entry.getValue().entrySet())
                {
                    updateSLO(mappers, builder, events, data, SLOConstants.SLOFlapStatus.values()[event.getValue()], event.getKey(), objectId, instance, sloId, correctedCycleId, false);
                }

                // update the last flap
                updateSLO(mappers, builder, events, data, getLastSLOStatus(data), endTime, objectId, instance, sloId, correctedCycleId, true);

                write(mappers, builder, ArchivedObjectConfigStore.getStore().getObjectIdById(objectId),
                        instance,
                        DatastoreConstants.DatastoreType.SLO_METRIC,
                        DatastoreConstants.PluginId.SLO_INSTANCE,
                        sloId + GROUP_SEPARATOR + correctedCycleId,
                        VisualizationConstants.VisualizationDataSource.SLO_INSTANCE.getName(),
                        endTime,
                        buildSLOCalculationEvent(data, correctedSLOCycle, sloContext.getFloat(SLOProfile.SLO_TARGET), sloContext.getFloat(SLOProfile.SLO_WARNING), instance, duration, availability));
            }

            // calculate global SLO data
            var data = new JsonObject().put(DURATION_LEFT, duration);

            var result = merge(events, correctedSLOCycle.getLong(SLOCycle.SLO_CYCLE_END_TIME));

            if (!result.isEmpty())
            {
                for (var index = 0; index < result.size(); index++)
                {
                    var event = result.getJsonObject(index);

                    updateSLO(mappers, builder, events, data, SLOFlapStatus.values()[event.getInteger(SLO_STATUS_FLAP)], event.getLong(TIME_STAMP), NOT_AVAILABLE, EMPTY_VALUE, sloId, correctedCycleId, false);
                }
            }

            // update the last flap
            updateSLO(mappers, builder, events, data, getLastSLOStatus(data), endTime, NOT_AVAILABLE, EMPTY_VALUE, sloId, correctedCycleId, true);

            var event = buildGlobalSLOCalculationEvent(data, correctedSLOCycle, sloContext.getFloat(SLOProfile.SLO_TARGET), sloContext.getFloat(SLOProfile.SLO_WARNING), correctedCycleId + EMPTY_VALUE, duration, availability);

            write(mappers, builder, sloId,
                    correctedCycleId + EMPTY_VALUE,
                    DatastoreConstants.DatastoreType.SLO_METRIC,
                    DatastoreConstants.PluginId.SLO,
                    EMPTY_VALUE,
                    VisualizationConstants.VisualizationDataSource.SLO.getName(),
                    endTime, event);

            if (MotadataConfigUtil.devMode())
            {
                vertx.eventBus().send("slo.calculation.test", event);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ SLO correction methods ------------------------ //

    private void correct(Map<String, TreeMap<Long, Integer>> sloEvents, List<long[]> correctionTimestamps, JsonArray entities)
    {
        if (entities != null)
        {
            for (var entity : entities)
            {
                var key = CommonUtil.getString(entity);

                var event = sloEvents.getOrDefault(key, null);

                if (event != null)
                {
                    applyCorrection(event, correctionTimestamps);
                }
                else
                {
                    LOGGER.warn(String.format("slo statuses not found for key: %s", key));
                }
            }
        }
        else
        {
            sloEvents.forEach((key, value) -> applyCorrection(value, correctionTimestamps));
        }
    }

    private void applyCorrection(TreeMap<Long, Integer> events, List<long[]> correctionTimestamps)
    {
        for (var timestamp : correctionTimestamps)
        {
            var start = timestamp[0];

            var end = timestamp[1];

            // ---- Find baseline status before correction starts ----
            var left = events.floorEntry(start);

            var baselineStatus = (left != null) ? left.getValue() : 0; // default UP if nothing before

            // ---- Ensure we have entry at start ----
            events.put(start, baselineStatus);

            // ---- Ensure we have entry at end ----
            var right = events.floorEntry(end);

            var restoreStatus = (right != null)
                    ? right.getValue()
                    : baselineStatus; // fallback to baseline if correction inside corrected range

            events.put(end, restoreStatus);

            // ---- Apply correction inside [start, end) ----
            for (var entry : events.subMap(start, true, end, false).entrySet())
            {
                entry.setValue(SLOConstants.SLOFlapStatus.CORRECTED.ordinal());
            }
        }
    }
