package com.mindarray.agent;

import com.mindarray.GlobalConstants;
import com.mindarray.api.Agent;
import com.mindarray.api.MotadataApp;
import com.mindarray.store.AgentCacheStore;
import com.mindarray.store.AgentConfigStore;
import com.mindarray.store.ArtifactConfigStore;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.DateTimeUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.MotadataApp.ARTIFACT_UPGRADE_STATUS;
import static com.mindarray.eventbus.EventBusConstants.*;

public class AgentUpgradeManager extends AbstractVerticle
{
    private static final int MAX_CONCURRENT_UPGRADES = MotadataConfigUtil.getConcurrentAgentUpgradeLimit();

    private final List<JsonObject> upgradeEvents = new ArrayList<>();

    private final Map<Long, Long> activeUpgrades = new HashMap<>();

    private static final Logger LOGGER = new Logger(AgentUpgradeManager.class, GlobalConstants.MOTADATA_AGENT, "Agent Upgrade Manager");

    private boolean timeHandlerActive = false;

    private int eventProbes;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        vertx.eventBus().<JsonObject>localConsumer(EVENT_AGENT_UPGRADE_QUEUE, message ->
        {
            if (!activeUpgrades.containsKey(message.body().getLong(ID)))
            {
                upgradeEvents.add(message.body());

                var id = message.body().getLong(ID);

                var artifact = ArtifactConfigStore.getStore().getItem(id)
                        .put(ARTIFACT_UPGRADE_STATUS, String.format("%s Upgrade Queued", message.body().getString(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name())))
                        .put(MESSAGE, String.format("upgrade queued at %s", DateTimeUtil.timestamp()));

                vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION, new JsonObject().put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_ARTIFACT.name()).put(EVENT_CONTEXT, artifact).put(MotadataApp.ARTIFACT_TYPE, BootstrapType.AGENT.name()).put(ID, id).put(EVENT_COPY_REQUIRED, false));

                publish(UI_NOTIFICATION_AGENT_UPGRADE_PROGRESS, message.body().put(ARTIFACT_UPGRADE_STATUS, String.format("%s Upgrade Queued", message.body().getString(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name()))).put(MESSAGE, String.format("upgrade queued at %s", DateTimeUtil.timestamp())));
            }
            else
            {
                LOGGER.warn(String.format("Duplicate upgrade event received for agent : %s", ObjectConfigStore.getStore().getAgentObjectName(message.body().getLong(ID))));
            }

            if (!timeHandlerActive)
            {
                eventProbes = 0;

                timeHandlerActive = true;

                vertx.setPeriodic(TimeUnit.SECONDS.toMillis(30), timer ->
                {
                    try
                    {
                        var iterator = upgradeEvents.listIterator();

                        if (iterator.hasNext())
                        {
                            eventProbes = 0;
                        }
                        else
                        {
                            eventProbes++;
                        }

                        processActiveUpgrades();

                        while (iterator.hasNext() && activeUpgrades.size() < MAX_CONCURRENT_UPGRADES)
                        {
                            var event = iterator.next();

                            var id = event.getLong(GlobalConstants.ID);

                            activeUpgrades.put(id, DateTimeUtil.currentSeconds());

                            vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_MANAGER, event.put(EVENT_COPY_REQUIRED, false));

                            var artifact = ArtifactConfigStore.getStore().getItem(id)
                                    .put(ARTIFACT_UPGRADE_STATUS, String.format("%s Upgrade Initiated", event.getString(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name())))
                                    .put(MESSAGE, String.format("upgrade started at %s", DateTimeUtil.timestamp()));

                            vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION, new JsonObject().put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.UPDATE_ARTIFACT.name()).put(EVENT_CONTEXT, artifact).put(MotadataApp.ARTIFACT_TYPE, BootstrapType.AGENT.name()).put(ID, id).put(EVENT_COPY_REQUIRED, false));

                            publish(UI_NOTIFICATION_AGENT_UPGRADE_PROGRESS, event.put(ARTIFACT_UPGRADE_STATUS, String.format("%s Upgrade Initiated", event.getString(SYSTEM_BOOTSTRAP_TYPE, BootstrapType.AGENT.name()))).put(MESSAGE, String.format("upgrade started at %s", DateTimeUtil.timestamp())));

                            iterator.remove();
                        }

                        if (eventProbes > 120) //max 120 probes... i.e. 60 minutes of inactivity
                        {
                            processActiveUpgrades();

                            activeUpgrades.clear();

                            //disable timer to save cpu cycle...

                            vertx.cancelTimer(timer);

                            timeHandlerActive = false;
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                });
            }

        }).exceptionHandler(LOGGER::error);

        promise.complete();
    }

    private void processActiveUpgrades()
    {
        activeUpgrades.entrySet().removeIf(entry ->
        {
            var id = entry.getKey();

            var timestamp = entry.getValue();

            var progress = AgentCacheStore.getStore().getProgress(id);

            // Condition 1: Upgrade completed
            if (progress != null && progress >= 15)
            {
                LOGGER.info(String.format("Successfully processed upgrade event for agent: %s", ObjectConfigStore.getStore().getAgentObjectName(id)));

                return true;
            }

            // Condition 2: Timeout (>= 10 minutes)
            if ((DateTimeUtil.currentSeconds() - timestamp) >= 600)
            {
                LOGGER.info(String.format("Upgrade event processing timed out for agent: %s", ObjectConfigStore.getStore().getAgentObjectName(id)));

                vertx.eventBus().send(EVENT_MANAGER_RESPONSE_PROCESSOR, new JsonObject()
                        .put(Agent.AGENT_UUID, AgentConfigStore.getStore().getAgentUUID(id)).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                        .put(GlobalConstants.PROGRESS, 100).put(REASON, "Agent upgrade event timed out")
                );

                return true;
            }

            return false;
        });
    }
}

