package com.mindarray.api;

import com.mindarray.Bootstrap;
import com.mindarray.ErrorCodes;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.GlobalConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.log.LogEngineConstants;
import com.mindarray.store.LogParserConfigStore;
import com.mindarray.store.LogParserPluginConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.util.MotadataConfigUtil;
import com.mindarray.util.WorkerUtil;
import com.zaxxer.nuprocess.NuAbstractProcessHandler;
import com.zaxxer.nuprocess.NuProcessBuilder;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import io.vertx.ext.web.Router;
import io.vertx.ext.web.RoutingContext;
import org.apache.commons.io.FileUtils;
import org.apache.http.HttpStatus;

import java.io.File;
import java.nio.ByteBuffer;
import java.util.concurrent.TimeUnit;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.RESPONSE_CODE;
import static com.mindarray.api.LogParser.LOG_PARSER_NAME;
import static com.mindarray.api.LogParser.LOG_PARSER_PLUGIN;
import static com.mindarray.util.WorkerUtil.EXIT_CODE_TIMED_OUT;

public class LogParserPlugin extends AbstractAPI
{
    public static final String LOG_PARSER_PLUGIN_NAME = "log.parser.plugin.name";
    public static final String LOG_PARSER_PLUGIN_CONTEXT = "log.parser.plugin.context";
    public static final String LOG_PARSER_PLUGIN_SCRIPT = "log.parser.plugin.script";
    private static final Logger LOGGER = new Logger(LogParserPlugin.class, MOTADATA_API, "Log Parser Plugin API");

    public LogParserPlugin()
    {
        super("log-parser-plugins", LogParserPluginConfigStore.getStore(), new Logger(LogParserPlugin.class, MOTADATA_API, "Log Parser Plugin API"));
    }

    @Override
    public void init(Router router)
    {
        try
        {
            super.init(router);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    @Override
    protected Future<JsonObject> beforeCreate(RoutingContext routingContext)
    {
        var promise = Promise.<JsonObject>promise();

        var error = ErrorMessageConstants.TIMED_OUT;

        try
        {
            var requestParameters = routingContext.body().asJsonObject();

            var fileName = requestParameters.getString(LOG_PARSER_PLUGIN_NAME).replace("-", "").replace(" ", "");

            createPlugin(requestParameters,fileName).onComplete(handler ->{

                if(handler.succeeded())
                {
                    promise.complete(handler.result());
                }
                else
                {
                    if(ErrorMessageConstants.LOG_PARSER_INVALID_PLUGIN_METHOD.equalsIgnoreCase(handler.cause().getMessage()))
                    {
                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                .put(MESSAGE, ErrorMessageConstants.LOG_PARSER_INVALID_PLUGIN_METHOD).put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST)
                                .put(GlobalConstants.ERROR, ErrorMessageConstants.LOG_PARSER_INVALID_PLUGIN_METHOD));

                        promise.fail(error);
                    }
                    else
                    {
                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST).put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                                .put(MESSAGE, error).put(ERROR_CODE, ErrorCodes.ERROR_CODE_BAD_REQUEST).put(GlobalConstants.ERROR, error));

                        promise.fail(error);
                    }
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    @Override
    protected Future<Void> afterCreate(JsonObject entity, RoutingContext routingContext)
    {
        this.send(routingContext, entity);

        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, entity.put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.ADD_LOG_PARSER_PLUGIN.name()));

        return Future.succeededFuture();
    }

    @Override
    protected Future<Void> afterDelete(JsonObject entity, RoutingContext routingContext)
    {
        this.send(routingContext, entity);

        Bootstrap.vertx().eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, entity.put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.DELETE_LOG_PARSER_PLUGIN.name()));

        return Future.succeededFuture();
    }

    @Override
    protected Future<JsonObject> getReferencesPreHook(RoutingContext routingContext, JsonObject response)
    {
        try
        {
            response = new JsonObject();

            var items = LogParserConfigStore.getStore().getItemsByValue(LOG_PARSER_PLUGIN, CommonUtil.getLong(routingContext.request().getParam(ID)));

            var results = new JsonArray();

            if (items != null && !items.isEmpty())
            {

                for (var index = 0; index < items.size(); index++)
                {
                    results.add(new JsonObject().put(LOG_PARSER_NAME, items.getJsonObject(index).getString(LOG_PARSER_NAME)));
                }

                response.put(APIConstants.Entity.LOG_PARSER.getName(), results);
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return Future.succeededFuture(response);
    }

    public static Future<JsonObject> createPlugin(JsonObject event,String fileName)
    {
        var promise = Promise.<JsonObject>promise();

        var error = ErrorMessageConstants.TIMED_OUT;

        try
        {
            var logFile = GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + PLUGIN_SCRIPT_DIR + GlobalConstants.PATH_SEPARATOR + PLUGIN_PARSER_DIR + PATH_SEPARATOR + fileName + ".java";

            Bootstrap.vertx().fileSystem().writeFileBlocking(logFile, Buffer.buffer(event.getJsonObject(LOG_PARSER_PLUGIN_CONTEXT).getString(LOG_PARSER_PLUGIN_SCRIPT)));

            var processBuilder = new NuProcessBuilder(MotadataConfigUtil.devMode() ? "javac" : GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "jdk" + GlobalConstants.PATH_SEPARATOR + "bin" + GlobalConstants.PATH_SEPARATOR + "javac", "-classpath", GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + "lib" + GlobalConstants.PATH_SEPARATOR + "*", logFile);

            var builder = new StringBuilder();

            var errors = new StringBuilder();

            processBuilder.setProcessListener(new NuAbstractProcessHandler()
            {
                @Override
                public void onStderr(ByteBuffer buffer, boolean closed)
                {
                    if (!closed)
                    {
                        var bytes = new byte[buffer.remaining()];

                        buffer.get(bytes);

                        var line = new String(bytes);

                        if (CommonUtil.isNotNullOrEmpty(line))
                        {
                            errors.append(line);

                            LOGGER.trace(String.format("custom log parser plugin %s errors : %s", event.getString(LOG_PARSER_PLUGIN_NAME), errors));
                        }

                        super.onStderr(buffer, false);
                    }
                }

                @Override
                public void onStdout(ByteBuffer buffer, boolean closed)
                {
                    if (!closed)
                    {
                        var bytes = new byte[buffer.remaining()];

                        buffer.get(bytes);

                        var line = new String(bytes);

                        if (CommonUtil.isNotNullOrEmpty(line))
                        {
                            builder.append(line);

                            if (CommonUtil.traceEnabled())
                            {
                                LOGGER.trace(String.format("custom log parser plugin %s output is %s", event.getString(LOG_PARSER_PLUGIN_NAME), line));
                            }
                        }

                        super.onStdout(buffer, false);
                    }
                }
            });

            var process = processBuilder.start();

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug(String.format("custom log parser plugin %s process %s started", event.getString(LOG_PARSER_PLUGIN_NAME), process.getPID()));
            }

            WorkerUtil.setupCleanupTimer(10, process, processBuilder, GlobalConstants.NOT_AVAILABLE);

            var exitCode = process.waitFor(11, TimeUnit.SECONDS);

            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug(String.format("custom log parser plugin process having PID %s exited with status code %s", process.getPID(), exitCode));
            }

            if (exitCode != EXIT_CODE_TIMED_OUT && exitCode != Integer.MIN_VALUE)
            {
                if (builder.isEmpty() && errors.indexOf("error") == -1 && errors.indexOf("ERROR") == -1 && errors.indexOf("Error") == -1)
                {
                    try
                    {
                        //validate class and method name [has to be 'parse']
                        Class.forName(GlobalConstants.PLUGIN_PARSER_DIR + "." + fileName, true, LogEngineConstants.LOG_PLUGIN_CLASS_LOADER).getDeclaredMethod(GlobalConstants.PARSE_METHOD, JsonObject.class);

                        promise.complete(event);
                    }

                    catch (Exception exception)
                    {
                        LOGGER.error(exception);

                        FileUtils.deleteQuietly(new File(GlobalConstants.PLUGIN_PARSER_DIR + "." + fileName));

                        promise.fail(ErrorMessageConstants.LOG_PARSER_INVALID_PLUGIN_METHOD);
                    }
                }
                else
                {
                    promise.fail(error);
                }
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }
}

