package com.mindarray.eventbus;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.datastore.DatastoreConstants;
import com.mindarray.util.*;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import io.vertx.core.net.*;
import io.vertx.core.parsetools.RecordParser;

import java.util.HashMap;
import java.util.Map;

import static com.mindarray.GlobalConstants.PORT;
import static com.mindarray.GlobalConstants.VALUE_SEPARATOR_WITH_ESCAPE;
import static com.mindarray.eventbus.EventBusConstants.*;

public class TCPServer implements TransportServer
{
    private final JsonObject config;

    private final String eventType;

    private NetServer server;

    private static final Logger LOGGER = new Logger(TCPServer.class, GlobalConstants.MOTADATA_EVENT_BUS, "TCP Server");

    private final Map<String, NetSocket> connections = new HashMap<>();

    private long timer;

    public TCPServer(JsonObject config)
    {
        this.config = config;

        this.eventType = config.getString(EVENT_TYPE);
    }

    @Override
    public Future<Void> bind()
    {
        var promise = Promise.<Void>promise();

        server = Bootstrap.vertx().createNetServer(new NetServerOptions().setReuseAddress(true).setReusePort(true)
                .setTcpFastOpen(true).setTcpKeepAlive(true).setTcpNoDelay(true).setSendBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes()).setReceiveBufferSize(MotadataConfigUtil.getTCPBufferSizeBytes()));

        recv();

        server.listen(config.getInteger(PORT))
                .onComplete(handler ->
                {
                    if (handler.succeeded())
                    {
                        LOGGER.info(String.format("server is successfully connected with port %s", config.getInteger(PORT)));

                        promise.complete();
                    }
                    else
                    {
                        promise.fail(handler.cause());
                    }
                });

        return promise.future();
    }

    @Override
    public void send(String uuid, byte[] data)
    {
        var socket = connections.get(uuid);

        if (socket != null)
        {
            socket.write(Buffer.buffer(data).appendString(VALUE_SEPARATOR_WITH_ESCAPE));

            if (CommonUtil.traceEnabled())
            {
                LOGGER.trace(String.format("sending data to : %s to port : %s ",uuid,config.getInteger(PORT)));
            }
        }
    }

    public Future<Void> recv()
    {
        connections.clear();

        server.connectHandler(socket ->
        {
            var remote = socket.remoteAddress();

            LOGGER.info(String.format("client is connected to server with address %s:%s at port : %s", remote.host(),remote.port(),config.getInteger(PORT)));

            socket.handler(buffer ->
            {
                if (buffer != null && buffer.length() > 0)
                {
                    var event = buffer.toJsonObject();

                    connections.put(event.getString(EVENT_TOPIC),socket);

                    RecordParser.newDelimited(VALUE_SEPARATOR_WITH_ESCAPE,socket).handler(bytes ->
                    {
                        if (bytes != null && bytes.length() > 0)
                        {
                            Bootstrap.vertx().eventBus().send(eventType,bytes.getBytes());

                            if (CommonUtil.traceEnabled())
                            {
                                LOGGER.trace(String.format("receiving data at port : %s ",config.getInteger(PORT)));
                            }
                        }
                    });
                }
            });

            socket.closeHandler(close ->
            {
                LOGGER.warn(String.format("client is closed with address %s", remote.host() + ":" + remote.port()));

                connections.entrySet().removeIf(entry -> entry.getValue() == socket);
            });

        }).exceptionHandler(throwable -> LOGGER.error(throwable.getCause()));

        keepAliveConnection();

        return Future.succeededFuture();
    }

    private void keepAliveConnection()
    {
        Bootstrap.vertx().cancelTimer(timer);

        var event = new JsonObject().put(EVENT_TYPE, DatastoreConstants.OperationType.CONNECTION_KEEP_ALIVE.name());

        var buffer = Buffer.buffer().appendBytes(new CipherUtil().encrypt(CodecUtil.compress(event.encode())));

        timer = Bootstrap.vertx().setPeriodic(60 * 1000L, timerId ->
        {
            for (var entry : connections.entrySet())
            {
                if (entry.getKey().contains(MOTADATA_MANAGER_TOPIC))
                {
                    entry.getValue().write(Buffer.buffer(event.encode().getBytes()).appendString(VALUE_SEPARATOR_WITH_ESCAPE));
                }
                else
                {
                    entry.getValue().write(buffer.appendString(VALUE_SEPARATOR_WITH_ESCAPE));
                }
            }
        });
    }

    @Override
    public Future<Void> receive()
    {
        return Future.succeededFuture();
    }

    @Override
    public Future<Void> close()
    {
        Bootstrap.vertx().cancelTimer(timer);

        LOGGER.info(String.format("server is closed ... event type : %s port : %s ",eventType,config.getInteger(PORT)));

        return server.close();
    }
}

