package com.mindarray.datastore;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.APIConstants;
import com.mindarray.api.RemoteEventProcessor;
import com.mindarray.api.User;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.util.*;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonObject;
import org.apache.commons.io.FileUtils;

import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.HashSet;
import java.util.Set;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID;
import static com.mindarray.datastore.DatastoreConstants.BATCH_FILE;
import static com.mindarray.db.DBConstants.DB_QUERY;
import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.nms.NMSConstants.CACHE_NAME;

public class ConfigDBManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(ConfigDBManager.class, GlobalConstants.MOTADATA_DB, "Config DB Event Manager");
    private final Set<String> items = new HashSet<>(); //items by uuid store last read file
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            if(Bootstrap.bootstrapType().name().equalsIgnoreCase(BootstrapType.OBSERVER.name()))
            {
                load();

                vertx.eventBus().<JsonObject>localConsumer(EVENT_REGISTRATION, event ->
                {
                    LOGGER.info(String.format("event %s ",event.body().encode()));

                    var uuid = event.body().getString(REMOTE_EVENT_PROCESSOR_UUID);

                    if(!items.contains(uuid))
                    {
                        Bootstrap.startEngine(new ConfigDatastoreObserverManager(EVENT_CONFIG_DB_WRITE + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getConfigDBWorkerInstances(), ConfigDatastoreObserverWorker.class.getCanonicalName(), true), ConfigDatastoreObserverManager.class.getCanonicalName() + " " + uuid, null)
                                .onComplete(handler ->
                                {
                                    if (handler.succeeded())
                                    {
                                        items.add(uuid);

                                        LOGGER.info(String.format("%s app registration event completed...",uuid));

                                        Bootstrap.vertx().fileSystem().writeFileBlocking(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + "bookmarks.json",Buffer.buffer(new JsonObject().put("bookmarks",items).encodePrettily().getBytes()));
                                    }
                                    else
                                    {
                                        LOGGER.error(handler.cause());
                                    }
                                });
                    }

                }).exceptionHandler(LOGGER::error);

                //config event received from primary server. observer write event base of app server.

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_DB_SYNC_WRITE, message -> items.forEach(entry->
                {
                    if (!entry.equalsIgnoreCase(message.body().getString(REMOTE_EVENT_PROCESSOR_UUID)))
                    {
                        vertx.eventBus().send(EVENT_CONFIG_DB_SYNC_FLUSH + GlobalConstants.DOT_SEPARATOR + entry,message.body());
                    }

                })).exceptionHandler(LOGGER::error);

                //cache event received from primary server. observer write event base of app server.

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CACHE_SYNC_WRITE, message -> items.forEach(entry->
                {
                    if (!entry.equalsIgnoreCase(message.body().getString(REMOTE_EVENT_PROCESSOR_UUID)))
                    {
                        vertx.eventBus().send(EVENT_CACHE_DB_WRITE + GlobalConstants.DOT_SEPARATOR + entry,message.body());
                    }

                })).exceptionHandler(LOGGER::error);

                //receive request from app server regrading latest config update

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_DB_SYNC_READ, message ->
                {
                    if(!items.isEmpty())
                    {
                        vertx.eventBus().send(EVENT_CONFIG_DB_READ + GlobalConstants.DOT_SEPARATOR + message.body().getString(REMOTE_EVENT_PROCESSOR_UUID),message.body());
                    }
                    else
                    {
                        vertx.eventBus().send(EVENT_PUBLICATION_MOTADATA_OBSERVER, new JsonObject()
                                .put(EVENT_TOPIC, REMOTE_EVENT_PROCESSOR_TOPIC)
                                .put(EVENT_COPY_REQUIRED, false)
                                .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID, message.body().getString(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID))
                                .put(EVENT_TYPE, EVENT_CONFIG_DB_SYNC_ACKNOWLEDGEMENT));
                    }

                }).exceptionHandler(LOGGER::error);

                //receive request from app server regrading latest cache update

                vertx.eventBus().<JsonObject>localConsumer(EVENT_CACHE_SYNC_READ, message -> vertx.eventBus().send(EVENT_CACHE_DB_READ + GlobalConstants.DOT_SEPARATOR + message.body().getString(REMOTE_EVENT_PROCESSOR_UUID),message.body())).exceptionHandler(LOGGER::error);
            }
            else
            {

                if(MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.PRIMARY.name()))
                {
                    //primary app server write config event

                    Bootstrap.startEngine(new ConfigDatastoreManager(EVENT_CONFIG_DB_WRITE, MotadataConfigUtil.getConfigDBWorkerInstances(), ConfigDatastoreWorker.class.getCanonicalName(), true), ConfigDatastoreManager.class.getCanonicalName(), null)
                            .onComplete(result ->
                            {
                                if (result.succeeded())
                                {
                                    LOGGER.info(String.format("%s App Config DB manager started...",Bootstrap.getRegistrationId()));

                                    // initial read request to observer server for latest config and cache event.

                                    vertx.setPeriodic(MotadataConfigUtil.getConfigDBRequestTimer(), handler ->
                                    {
                                        if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                                        {
                                            vertx.eventBus().send(EVENT_HA_OBSERVER,
                                                    new JsonObject().put(EVENT_TYPE, EVENT_CONFIG_DB_SYNC_READ)
                                                            .put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                                            .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId()));

                                            LOGGER.info(String.format("App %s server send config event request",InstallationMode.PRIMARY.name()));

                                            vertx.eventBus().send(EVENT_HA_OBSERVER,
                                                    new JsonObject().put(EVENT_TYPE,EVENT_CACHE_SYNC_READ)
                                                            .put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                                            .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId()));

                                            LOGGER.info(String.format("App %s server send cache event request",InstallationMode.PRIMARY.name()));
                                        }
                                        else
                                        {
                                            LOGGER.warn(String.format("Observer server is down , address : %s ",MotadataConfigUtil.getRemoteEventObserverPublisher() + ":"+ MotadataConfigUtil.getMotadataObserverEventPublisherPort()));
                                        }

                                        if(Bootstrap.isSynced())
                                        {
                                            vertx.cancelTimer(handler);
                                        }
                                    });
                                }
                                else
                                {
                                    LOGGER.error(result.cause());
                                }
                            });
                }
                else
                {
                    //secondary and failover app server read request to observer server for latest config and cache event

                    vertx.setPeriodic(MotadataConfigUtil.getConfigDBRequestTimer(), handler ->
                    {
                        if (PortUtil.isConnected(MotadataConfigUtil.getRemoteEventObserverPublisher(), MotadataConfigUtil.getMotadataObserverEventPublisherPort(), 3))
                        {
                            vertx.eventBus().send(EVENT_HA_OBSERVER, new JsonObject().put(EVENT_TYPE, EVENT_CONFIG_DB_SYNC_READ).put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                    .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId()));

                            LOGGER.info(String.format("App %s server send config event request",MotadataConfigUtil.getInstallationMode()));

                            vertx.eventBus().send(EVENT_HA_OBSERVER, new JsonObject().put(EVENT_TYPE,EVENT_CACHE_SYNC_READ).put(INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode())
                                    .put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,Bootstrap.getRegistrationId()));

                            LOGGER.info(String.format("App %s server send cache event request",MotadataConfigUtil.getInstallationMode()));
                        }
                        else
                        {
                            LOGGER.warn(String.format("Observer server is down , address : %s ",MotadataConfigUtil.getRemoteEventObserverPublisher() + ":"+ MotadataConfigUtil.getMotadataObserverEventPublisherPort()));
                        }
                    });
                }

                //receive response from observer server to decode config event and update config db
                vertx.eventBus().<JsonObject>localConsumer(EVENT_CONFIG_DB_SYNC_FLUSH, event -> decodeEvent(event.body()));

                //receive response from observer server to decode cache event and update cache file
                vertx.eventBus().<JsonObject>localConsumer(EVENT_CACHE_SYNC_FLUSH, event -> updateCache(event.body()));
            }

            promise.complete();
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void load()
    {
        try
        {
            var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + "bookmarks.json");

            if (file.exists() && file.length() > 0)
            {
                var context = new JsonObject(FileUtils.readFileToString(file, StandardCharsets.UTF_8));

                if (!context.isEmpty())
                {
                    var uuids = context.getJsonArray("bookmarks");

                    for (var index = 0; index < uuids.size();index++)
                    {
                        var uuid = uuids.getString(index);

                        Bootstrap.startEngine(new ConfigDatastoreObserverManager(EVENT_CONFIG_DB_WRITE + GlobalConstants.DOT_SEPARATOR + uuid, MotadataConfigUtil.getConfigDBWorkerInstances(), ConfigDatastoreObserverWorker.class.getCanonicalName(), true), ConfigDatastoreObserverManager.class.getCanonicalName() + " " + uuid, null)
                                .onComplete(handler ->
                                {
                                    if (handler.succeeded())
                                    {
                                        items.add(uuid);

                                        LOGGER.info(String.format("%s app registration event completed...",uuid));
                                    }
                                    else
                                    {
                                        LOGGER.error(handler.cause());
                                    }
                                });

                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void updateCache(JsonObject context)
    {
        try
        {
            LOGGER.info(String.format("received updated cache file %s ",context.getString(CACHE_NAME)));

            Bootstrap.vertx().fileSystem().writeFileBlocking(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + context.getString(CACHE_NAME), Buffer.buffer(context.getBinary(RESULT)));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
    private void updateConfig(JsonObject context)
    {
        try
        {
            if(context.containsKey(DBConstants.HA_OPERATION))
            {
                var collection = context.getString(APIConstants.ENTITY_COLLECTION);

                var type = DBConstants.HAOperation.valueOfName(CommonUtil.getByteValue(context.getValue(DBConstants.HA_OPERATION)));

                if(collection != null)
                {
                    LOGGER.info(String.format("performing operation %s on collection %s",type,collection));

                    LOGGER.trace(String.format("context : %s",context.encode()));
                }

                switch (type)
                {
                    case SAVE ->
                    {
                        if(!context.containsKey(EventBusConstants.EVENT_ROUTER_CONFIG))
                        {
                            Bootstrap.configDBService().save(collection, context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                                    handler ->
                                    {
                                        if (handler.succeeded())
                                        {
                                            LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                        }
                                        else
                                        {
                                            LOGGER.error(handler.cause());

                                            LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                        }
                                    });
                        }
                        else
                        {
                            var cacheFile = context.getString(CACHE_NAME);

                            if (CommonUtil.isNotNullOrEmpty(cacheFile) && context.getBinary(GlobalConstants.RESULT) != null && context.getBinary(RESULT).length > 0)
                            {
                                LOGGER.info(String.format("received updated cache file %s ",cacheFile));

                                Bootstrap.vertx().fileSystem().writeFileBlocking(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + cacheFile,
                                        Buffer.buffer(context.getBinary(RESULT)));
                            }
                        }
                    }

                    case SAVE_ALL -> Bootstrap.configDBService().saveAll(collection, context.getJsonArray(DBConstants.DB_DOCUMENTS), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));

                                }
                            });

                    case UPDATE -> Bootstrap.configDBService().update(collection, context.getJsonObject(DBConstants.DB_QUERY), context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());
                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));

                                }
                            });

                    case UPDATE_ALL -> Bootstrap.configDBService().updateAll(collection, context.getJsonObject(DBConstants.DB_QUERY), context.getJsonObject(DBConstants.DB_DOCUMENTS), context.getString(User.USER_NAME), context.getString(GlobalConstants.REMOTE_ADDRESS),
                            handler ->
                            {
                                if (handler.succeeded())
                                {
                                    LOGGER.trace(String.format("collection %s , type %s successfully",collection,type));
                                }
                                else
                                {
                                    LOGGER.error(handler.cause());

                                    LOGGER.info(String.format("error found in %s ",context.encodePrettily()));
                                }
                            });

                    case UPSERT -> Bootstrap.configDBService().upsert(collection,context.getJsonObject(DB_QUERY),context.getJsonArray(DBConstants.DB_DOCUMENTS).getJsonObject(0),SYSTEM_USER,SYSTEM_REMOTE_ADDRESS, result ->
                    {
