    /**
     * Sends a flush notification for deleted metric instances to the database for each plugin.
     *
     * @param plugins the list of plugin IDs to notify
     * @param id the object or metric ID associated with the deleted instances
     * @param values the values or instances to be flushed/deleted
     */
    public static void send(JsonArray plugins, long id,  JsonArray values, Logger LOGGER)
    {
        for (var i = 0; i < plugins.size(); i++)
        {
            var plugin = plugins.getInteger(i) + DASH_SEPARATOR + MetricConfigStore.getStore().getMetricName(plugins.getInteger(i));

            var buffer = Buffer.buffer();

            LOGGER.info("Deleted Instance/Object send for Db : plugin : " + plugin + " id : " + id + " values : " + values);

            buffer.appendByte(DatastoreConstants.OperationType.FLUSH_DELETED_INSTANCES.getName()).appendBytes(new JsonObject().put(plugin, new JsonObject().put(CommonUtil.getString(id), values)).encode().getBytes());

            //Send Notification to db for updated metrics
            VisualizationConstants.send(buffer);
        }
    }

