    private static final Set<AbstractConfigStore.ConfigStore> PASSOVER_CONFIG_STORES = Set.of(AbstractConfigStore.ConfigStore.METRIC, AbstractConfigStore.ConfigStore.TAG, AbstractConfigStore.ConfigStore.SCHEDULER);
    private static final Set<AbstractCacheStore.CacheStore> PASSOVER_CACHE_STORES = Set.of(AbstractCacheStore.CacheStore.OBJECT_MANAGER, AbstractCacheStore.CacheStore.TAG, AbstractCacheStore.CacheStore.METRIC_POLICY_FLAP_DURATION, AbstractCacheStore.CacheStore.NETROUTE_POLICY_FLAP_DURATION, AbstractCacheStore.CacheStore.TOPOLOGY);
