package com.mindarray.runbook;

import com.mindarray.Bootstrap;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.GlobalConstants;
import com.mindarray.api.AIOpsObject;
import com.mindarray.api.Integration;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.eventbus.EventEngine;
import com.mindarray.policy.PolicyEngineConstants;
import com.mindarray.store.IntegrationCacheStore;
import com.mindarray.store.IntegrationConfigStore;
import com.mindarray.store.MetricPolicyConfigStore;
import com.mindarray.store.ObjectConfigStore;
import com.mindarray.util.*;
import io.vertx.core.AbstractVerticle;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.buffer.Buffer;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import org.apache.http.HttpStatus;

import java.io.File;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;

import static com.mindarray.ErrorMessageConstants.API_ACCESS_FAILED_NOT_AUTHORIZED;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.*;
import static com.mindarray.api.Integration.*;
import static com.mindarray.eventbus.EventBusConstants.*;

public class IntegrationEngine extends AbstractVerticle
{

    public static final String TICKET_ID = "ticket.id";

    public static final String INTEGRATIONS = "integrations";

    public static final String INTEGRATIONS_PENDING_EVENTS = "integrations-pending-events";

    public static final String INTEGRATION_ACCESS_TOKEN = "access_token";

    public static final Map<String, String> INTEGRATION_TYPES = Map.ofEntries(Map.entry(Runbook.RunbookPluginType.SERVICEOPS_TICKET.getName(), "ServiceOps"));
    private static final Logger LOGGER = new Logger(IntegrationEngine.class, RUNBOOK_DIR, "Integration Engine");
    private static final String REPLY_TOPIC = EVENT_INTEGRATION + EventBusConstants.EVENT_REPLY;
    private static final String DESCRIPTION_TEMPLATE = "<ul><li><p>Object Name: <strong>$$$object.name$$$</strong></p></li><li><p>IP / Host: <strong>$$$object.ip$$$</strong></p></li><li><p>Object Type: <strong>$$$object.type$$$</strong></p></li><li><p>Metric: <strong>$$$counter$$$</strong></p></li><li><p>Metric Value: <strong>$$$value$$$</strong></p></li><li><p>Severity: <strong>$$$severity$$$</strong></p></li><li><p>Policy Name: <strong>$$$policy.name$$$</strong></p></li><li><p>Policy Type: <strong>$$$policy.type$$$</strong></p></li><li><p>Message: <strong>$$$policy.message$$$</strong></p></li></ul>";
    private static final int PENDING_EVENT_FLUSH_TIMER_SECONDS = MotadataConfigUtil.getIntegrationPendingEventFlushTimerSeconds();
    private final AtomicBoolean updated = new AtomicBoolean();
    private final List<JsonObject> pendingEvents = new ArrayList<>();
    private final Map<String, Boolean> integrationPingTimers = new HashMap<>();
    private EventEngine integrationEngine;

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        var file = new File(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + INTEGRATIONS_PENDING_EVENTS);

        if (file.exists())
        {
            var buffer = Bootstrap.vertx().fileSystem().readFileBlocking(file.getPath());

            if (buffer != null && buffer.getBytes().length > 0)
            {
                var context = new JsonArray(Buffer.buffer(CodecUtil.toBytes(buffer.getBytes())));

                if (!context.isEmpty())
                {
                    for (var index = 0; index < pendingEvents.size(); index++)
                    {
                        pendingEvents.add(context.getJsonObject(index));
                    }
                }
            }
        }
        else
        {
            Bootstrap.vertx().fileSystem().createFileBlocking(file.getPath());
        }

        var refreshTimer = new AtomicInteger(PENDING_EVENT_FLUSH_TIMER_SECONDS);

        vertx.setPeriodic(30 * 1000L, timer ->
        {
            if (updated.get())
            {
                updated.set(false);

                vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + INTEGRATIONS_PENDING_EVENTS,
                        Buffer.buffer(CodecUtil.compress(pendingEvents.toString().getBytes())));
            }

            refreshTimer.set(refreshTimer.get() - 30);

            if (refreshTimer.get() <= 0)
            {
                vertx.fileSystem().writeFileBlocking(GlobalConstants.CURRENT_DIR + GlobalConstants.PATH_SEPARATOR + GlobalConstants.CONFIG_DIR + GlobalConstants.PATH_SEPARATOR + INTEGRATIONS_PENDING_EVENTS,
                        Buffer.buffer(CodecUtil.compress(pendingEvents.toString().getBytes())));

                refreshTimer.set(PENDING_EVENT_FLUSH_TIMER_SECONDS);
            }

        });

        vertx.eventBus().<JsonObject>localConsumer(EVENT_INTEGRATION_PING_ACTIVE, message ->

                vertx.setPeriodic(MotadataConfigUtil.getIntegrationPingTimerSeconds() * 1000L, handler ->
                {

                    if (!integrationPingTimers.isEmpty())
                    {
                        for (var entry : integrationPingTimers.entrySet())
                        {
                            if (IntegrationType.SERVICEOPS.getName().equalsIgnoreCase(entry.getKey()))
                            {
                                ping(IntegrationType.SERVICEOPS.getName()).onComplete(result ->
                                {

                                    if (result.succeeded())
                                    {
                                        vertx.cancelTimer(handler);

                                        while (!pendingEvents.isEmpty())
                                        {
                                            process(pendingEvents.remove(0));
                                        }

                                        integrationPingTimers.put(IntegrationType.SERVICEOPS.getName(), false);
                                    }
                                });

                                //To-do: logging error and success...
                            }
                        }
                    }
                }));

        vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
        {

            switch (ChangeNotificationType.valueOf(message.body().getString(CHANGE_NOTIFICATION_TYPE)))
            {

                case UPDATE_INTEGRATION ->
                {
                    while (!pendingEvents.isEmpty())
                    {
                        process(pendingEvents.remove(0));
                    }
                }
                case DELETE_POLICY ->
                {
                    var policy = MetricPolicyConfigStore.getStore().getItem(message.body().getLong(ID));

                    if(policy != null && !policy.isEmpty())
                    {
                        IntegrationCacheStore.getStore().remove(policy.getString(ID));
                    }
                }
            }
        }).exceptionHandler(LOGGER::error);

        integrationEngine = new EventEngine().setEventType(EVENT_INTEGRATION).setEventQueueSize(20)
                .setBlockingEvent(true).setLogger(LOGGER).setEventHandler(this::process).start(vertx, promise);
    }

    private Future<Void> ping(String integrationType)
    {
        var promise = Promise.<Void>promise();

        if (integrationType.equalsIgnoreCase(IntegrationType.SERVICEOPS.getName()))
        {
            vertx.eventBus().<JsonObject>request(EVENT_INTEGRATION_AUTH_TOKEN_CREATE, IntegrationConfigStore.getStore().getItemByValue(Integration.INTEGRATION_TYPE, IntegrationType.SERVICEOPS.getName()).put(EVENT_COPY_REQUIRED, false), result ->
            {
                if (result.succeeded())
                {
                    if (result.result().body().containsKey(STATUS) && STATUS_FAIL.equalsIgnoreCase(result.result().body().getString(STATUS)))
                    {
                        promise.fail(result.result().body().encode());
                    }
                    else
                    {
                        promise.complete();
                    }
                }
                else
                {
                    promise.fail(result.cause().getMessage());
                }
            });
        }

        return promise.future();
    }

    public void process(JsonObject event)
    {
        if (event != null && event.getString(Integration.INTEGRATION_TYPE).equalsIgnoreCase(IntegrationType.SERVICEOPS.getName()))
        {
            var item = IntegrationConfigStore.getStore().getItemByValue(Integration.INTEGRATION_TYPE, IntegrationType.SERVICEOPS.getName());

            if (event.containsKey(TICKET_ID)) //Update Ticket
            {
                event.put(INTEGRATION_SERVER_TICKET_UPDATION_API, item.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? item.getString(INTEGRATION_SERVER_URL) + "api/request/" + event.getString(TICKET_ID).split("-")[1] + "/conversation" : item.getString(INTEGRATION_SERVER_URL) + "/" + "api/request/" + event.getString(TICKET_ID).split("-")[1] + "/conversation");

                if(Severity.CLEAR.name().equalsIgnoreCase(event.getString(SEVERITY)))
                {
                    IntegrationCacheStore.getStore().remove(IntegrationType.SERVICEOPS.getName(), event.getString(ID) + SEPARATOR + event.getString(PolicyEngineConstants.POLICY_KEY));
                }

                if(Severity.CLEAR.name().equalsIgnoreCase(event.getString(SEVERITY)) && YES.equalsIgnoreCase(item.getString("auto.close.ticket")))
                {
                    LOGGER.info(String.format("Update Request for Auto close, ticket status : %s",item.getString("ticket.status")));

                    invoke(event, item,new JsonObject().put("statusName",item.getString("ticket.status")), item.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? item.getString(INTEGRATION_SERVER_URL) + "api/v1/request/" + event.getString(TICKET_ID).split("-")[1] : item.getString(INTEGRATION_SERVER_URL) + "/" + "api/v1/request/" + event.getString(TICKET_ID).split("-")[1]);
                }
                else
                {
                    invoke(event, item, event.getString(INTEGRATION_SERVER_TICKET_UPDATION_API), false);
                }
            }
            else  //Create Ticket
            {
                event.put(INTEGRATION_SERVER_TICKET_CREATION_API, item.getString(INTEGRATION_SERVER_URL).trim().endsWith("/") ? item.getString(INTEGRATION_SERVER_URL) + "api/v1/request" : item.getString(INTEGRATION_SERVER_URL) + "/" + "api/v1/request");

                invoke(event, item, event.getString(INTEGRATION_SERVER_TICKET_CREATION_API), true);
            }
        }
    }

    private void invoke(JsonObject event, JsonObject item, String url, boolean create)
    {
        WebClientUtil.getWebClient().postAbs(url)
                .bearerTokenAuthentication(item.getString(INTEGRATION_ACCESS_TOKEN)).putHeader("Content-Type", "application/json").sendJsonObject(create ? prepareRequestContext(event, item) : prepareRequestContext(event), handler ->
                {
                    if (handler.succeeded())
                    {
                        var result = handler.result();

                        if (result.statusCode() == HttpStatus.SC_UNAUTHORIZED)
                        {
                            LOGGER.warn(String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_TICKET_CREATION_API)));

                            updated.set(true);

                            vertx.eventBus().send(EVENT_INTEGRATION_AUTH_TOKEN_CREATE,item.put(REQUEST,REQUEST_UPDATE));

                            pendingEvents.add(event);

                        }
                        else if (result.statusCode() == HttpStatus.SC_BAD_REQUEST)
                        {
                            LOGGER.warn(String.format("Invalid credentials for url %s", event.getString(INTEGRATION_SERVER_TICKET_CREATION_API)));

                            updated.set(true);

                            pendingEvents.add(event);
                        }
                        else if (result.statusCode() == HttpStatus.SC_OK)
                        {
                            if (create)
                            {
                                LOGGER.info(String.format("Ticket: %s created Successfully", result.bodyAsJsonObject().getString("subject")));

                                IntegrationCacheStore.getStore().updateItem(Integration.IntegrationType.SERVICEOPS.getName(),event.getString(ID) + SEPARATOR + event.getString(PolicyEngineConstants.POLICY_KEY), result.bodyAsJsonObject().getString("name"), event.getLong(EVENT_TIMESTAMP), event.getString(SEVERITY));
                            }
                            else
                            {
                                LOGGER.info(String.format("Ticket: %s updated Successfully", event.getString(TICKET_ID)));
                            }

                            vertx.eventBus().send(REPLY_TOPIC, event.put(RESULT,result.bodyAsJsonObject()));

                        }

                    }
                    else
                    {

                        LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s", event.getString(Integration.INTEGRATION_TYPE)));

                        if (!integrationPingTimers.getOrDefault(IntegrationType.SERVICEOPS.getName(), false)) //when ServiceOps server goes down, start timer
                        {
                            vertx.eventBus().send(EVENT_INTEGRATION_PING_ACTIVE, new JsonObject());

                            integrationPingTimers.put(IntegrationType.SERVICEOPS.getName(), true);
                        }

                        updated.set(true);

                        pendingEvents.add(event);
                    }
                });
    }

    private void invoke(JsonObject event, JsonObject item, JsonObject payload, String url)
    {
        WebClientUtil.getWebClient().patchAbs(url)
                .bearerTokenAuthentication(item.getString(INTEGRATION_ACCESS_TOKEN)).putHeader("Content-Type", "application/json").sendJsonObject(payload, handler ->
                {
                    if (handler.succeeded())
                    {
                        var result = handler.result();

                        if (result.statusCode() == HttpStatus.SC_UNAUTHORIZED)
                        {
                            LOGGER.warn(String.format(API_ACCESS_FAILED_NOT_AUTHORIZED, event.getString(INTEGRATION_SERVER_TICKET_CREATION_API)));

                            updated.set(true);

                            pendingEvents.add(event);

                            vertx.eventBus().send(EVENT_INTEGRATION_AUTH_TOKEN_CREATE,item.put(REQUEST,REQUEST_UPDATE));

                        }
                        else if (result.statusCode() == HttpStatus.SC_BAD_REQUEST)
                        {
                            LOGGER.warn(String.format("Invalid credentials for url %s", event.getString(INTEGRATION_SERVER_TICKET_CREATION_API)));

                            updated.set(true);

                            pendingEvents.add(event);
                        }
                        else if (result.statusCode() == HttpStatus.SC_OK)
                        {

                            LOGGER.info(String.format("Ticket: %s updated Successfully", event.getString(TICKET_ID)));

                            vertx.eventBus().send(REPLY_TOPIC, event.put(RESULT,result.bodyAsJsonObject()));

                        }

                    }
                    else
                    {

                        LOGGER.warn(String.format(ErrorMessageConstants.INTERNAL_ERROR + ": integration with %s", event.getString(Integration.INTEGRATION_TYPE)));

                        if (!integrationPingTimers.getOrDefault(IntegrationType.SERVICEOPS.getName(), false)) //when ServiceOps server goes down, start timer
                        {
                            vertx.eventBus().send(EVENT_INTEGRATION_PING_ACTIVE, new JsonObject());

                            integrationPingTimers.put(IntegrationType.SERVICEOPS.getName(), true);
                        }

                        updated.set(true);

                        pendingEvents.add(event);
                    }
                });
    }

    private JsonObject prepareRequestContext(JsonObject event, JsonObject item)
    {
        var params = new JsonObject()
                .put("requesterName", "Motadata")
                .put("impactName", "On department")
                .put("statusName", "Open")
                .put("departmentName", "IT")
                .put("source", item.getString("source"));

        var policy = MetricPolicyConfigStore.getStore().getItem(event.getLong(ID));

        if (policy != null)
        {
            params.put("description", PolicyEngineConstants.replaceMetricPolicyPlaceholders(policy, event, DESCRIPTION_TEMPLATE, event.getString(MESSAGE)));
        }

        if (event.containsKey(INSTANCE))
        {
            params.put("subject", event.getString(SEVERITY) + " - " + event.getString(AIOpsObject.OBJECT_NAME) + " (" + event.getString(AIOpsObject.OBJECT_IP) + ")" + " - " + event.getString(METRIC) + " - " + event.getString(INSTANCE, ""));
        }
        else
        {
            params.put("subject", event.getString(SEVERITY) + " - " + event.getString(AIOpsObject.OBJECT_NAME) + " (" + event.getString(AIOpsObject.OBJECT_IP) + ")" + " - " + event.getString(METRIC));
        }

        params.put("requesterEmail", item.getString(USERNAME));

        var urgencyTypes = item.getJsonObject("urgency");

        if (urgencyTypes != null && !urgencyTypes.isEmpty())
        {
            for (var entry : urgencyTypes)
            {
                if (event.getString(SEVERITY).equalsIgnoreCase(CommonUtil.getString(entry.getValue())))
                {
                    params.put("urgencyName", entry.getKey());
                }
            }
        }

        var tags = ObjectConfigStore.getStore().getItem(event.getLong(ENTITY_ID)).getJsonArray(AIOpsObject.OBJECT_USER_TAGS);

        if (tags != null && !tags.isEmpty())
        {
            params.put("tags", tags);
        }

        LOGGER.info(String.format("Create Request payload: %s",params));

        return params;
    }

    private JsonObject prepareRequestContext(JsonObject event)
    {
        var params = new JsonObject()
                .put("conversationType", "note")
                .put("noteAsFirstResponse", false)
                .put("conversationState", "published");

        var policy = MetricPolicyConfigStore.getStore().getItem(event.getLong(ID));

        if (policy != null)
        {
            params.put("details", PolicyEngineConstants.replaceMetricPolicyPlaceholders(policy, event, DESCRIPTION_TEMPLATE, event.getString(MESSAGE)));
        }

        LOGGER.info(String.format("Update Request payload: %s",params));

        return params;
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        integrationEngine.stop(vertx, promise);
    }
}

