import static com.mindarray.GlobalConstants.*;
import static com.mindarray.eventbus.EventBusConstants.CHANGE_NOTIFICATION_TYPE;
import static com.mindarray.eventbus.EventBusConstants.EVENT_CHANGE_NOTIFICATION;

public class SLOManager extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(SLOProcessor.class, GlobalConstants.MOTADATA_SLO, "SLO Manager", true);

    private final Map<Long, Map<SLOConstants.SLOType, List<Long>>> sloProfilesByObject = new HashMap<>();

    private EventEngine eventEngine;

    // ------------------------ Verticle related methods ------------------------ //

    /**
     * Starts the SLO Manager verticle and initializes SLO profile registration and event handlers.
     * Sets up periodic cache flushing and registers event bus consumers for change notifications.
     *
     * @param promise the promise to complete when startup is finished
     * @throws Exception if startup fails
     */
    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        try
        {
            // Register all active SLO profiles at verticle start
            registerSLOProfiles(SLOProfileConfigStore.getStore().getActiveSLOProfiles());

            // cache flush related logic
            var refreshTimer = new AtomicInteger(MotadataConfigUtil.getSLOCacheFlushTimerSeconds());

            vertx.setPeriodic(TimeUnit.SECONDS.toMillis(30), timer ->
            {
                refreshTimer.addAndGet(-30);

                if (SLOCalculatorCacheStore.getStore().updated())
                {
                    SLOCalculatorCacheStore.getStore().dump(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + SLOConstants.SLO_CACHE_FILE);

                    SLOCalculatorCacheStore.getStore().setUpdate(false);
                }
                else if (refreshTimer.get() <= 0)
                {
                    SLOCalculatorCacheStore.getStore().dump(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + SLOConstants.SLO_CACHE_FILE);

                    refreshTimer.set(MotadataConfigUtil.getSLOCacheFlushTimerSeconds());
                }
            });

            vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
            {
                try
                {
                    var event = message.body();

                    if (message.body().getString(CHANGE_NOTIFICATION_TYPE, EMPTY_VALUE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.UPDATE_CACHE.name()))
                    {
                        if (SLOCalculatorCacheStore.getStore().dirty())
                        {
                            SLOCalculatorCacheStore.getStore().setDirty(false);

                            HAConstants.notifyObserver(new JsonObject().put(HAConstants.CACHE_NAME, SLOConstants.SLO_CACHE_FILE).put(RESULT, vertx.fileSystem().readFileBlocking(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + SLOConstants.SLO_CACHE_FILE)));
                        }
                    }
                    else if (message.body().getString(CHANGE_NOTIFICATION_TYPE, EMPTY_VALUE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.DELETE_SLO_PROFILE.name()))
                    {
                        var sloProfileId = event.getLong(ID);

                        if (sloProfileId == null)
                        {
                            LOGGER.warn("DELETE_SLO_PROFILE event received with null profile ID");

                            return;
                        }

                        var iterator = sloProfilesByObject.entrySet().iterator();

                        while (iterator.hasNext())
                        {
                            var entry = iterator.next();

                            var types = entry.getValue();

                            // Use iterator to safely remove from types map
                            var typeIterator = types.entrySet().iterator();

                            while (typeIterator.hasNext())
                            {
                                var type = typeIterator.next();

                                // Remove the SLO profile ID from the list
                                type.getValue().remove(sloProfileId);

                                // Remove the type entry if the list is now empty
                                if (type.getValue().isEmpty())
                                {
                                    typeIterator.remove();
                                }
                            }

                            // Remove the object entry if no types left
                            if (types.isEmpty())
                            {
                                iterator.remove();
                            }
                        }
                    }
                    else if (message.body().getString(CHANGE_NOTIFICATION_TYPE, EMPTY_VALUE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.DELETE_OBJECT.name()))
                    {
                        handleObjectDeletion(event);
                    }
                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
            });

            vertx.eventBus().localConsumer(EventBusConstants.EVENT_SLO_CYCLE_QUALIFY, message ->qualify());

            eventEngine = new EventEngine().setEventType(EventBusConstants.EVENT_AVAILABILITY_SLO_UPDATE)
                    .setPersistEventOffset(true).setLogger(LOGGER).setEventHandler(this::process).start(vertx, promise);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }
    }

    /**
     * Stops the SLO Manager verticle and performs cleanup operations.
     * Dumps the SLO calculator cache before shutdown.
     *
     * @param promise the promise to complete when shutdown is finished
     * @throws Exception if shutdown fails
     */
    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        SLOCalculatorCacheStore.getStore().dump(CURRENT_DIR + PATH_SEPARATOR + CONFIG_DIR + PATH_SEPARATOR + SLOConstants.SLO_CACHE_FILE);

        LOGGER.info("SLO Manager undeployed...");

        eventEngine.stop(vertx, promise);
    }

    // ------------------------ Availability SLO processing related methods ------------------------ //

    /**
     * Processes availability SLO update events received from {@link com.mindarray.store.ObjectStatusCacheStore} and routes them to appropriate SLO profiles.
     *
     * @param event the availability SLO update event
     */
    private void process(JsonObject event)
    {
        try
        {
            var objectId = event.getLong(AIOpsConstants.ENTITY_ID, -1L);

            var types = sloProfilesByObject.get(objectId);

            if (types != null)
            {
                var availabilitySLOs = types.get(SLOConstants.SLOType.AVAILABILITY);

                if (availabilitySLOs != null)
                {
                    availabilitySLOs.forEach(id ->
                            vertx.eventBus().send(EventBusConstants.EVENT_SLO_UPDATE, event
                                    .put(SLOCycle.SLO_PROFILE_ID, id)
                                    .put(EventBusConstants.EVENT_TYPE, SLOConstants.SLOEventType.SLO_PROCESS.getName())));
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ SLO Cycle related methods ------------------------ //

    /**
     * Qualifies SLO cycles for starting or ending based on current time.
     * Processes all SLO profiles to determine which cycles need to be started or ended.
     */
    private void qualify()
    {
        var cyclesToEnd = new JsonArray();

        var cyclesToStart = new JsonArray();

        var future = Promise.<Void>promise();

        qualifyCycles(SLOProfileConfigStore.getStore().getItems(), cyclesToEnd, cyclesToStart, new AtomicInteger(0), future);

        future.future().onComplete(result->
        {
            if (CommonUtil.debugEnabled())
            {
                LOGGER.debug(String.format("cycles to end : %s, cycles to start : %s", cyclesToEnd, cyclesToStart));
            }

            for (var index = 0; index < cyclesToEnd.size(); index++)
            {
                vertx.eventBus().send(EventBusConstants.EVENT_SLO_UPDATE, cyclesToEnd.getJsonObject(index));
            }

            for (var index = 0; index < cyclesToStart.size(); index++)
            {
                vertx.eventBus().send(EventBusConstants.EVENT_SLO_UPDATE, cyclesToStart.getJsonObject(index));
            }
        });
    }

    /**
     * Recursively qualifies SLO cycles for each profile to determine start/end actions.
     *
     * @param items the array of SLO profiles to process
     * @param cyclesToEnd the array to collect cycles that need to end
     * @param cyclesToStart the array to collect cycles that need to start
     * @param index the current processing index
     * @param promise the promise to complete when all cycles are qualified
     */
    private void qualifyCycles(JsonArray items, JsonArray cyclesToEnd, JsonArray cyclesToStart, AtomicInteger index, Promise<Void> promise)
    {
        try
        {
            var currentTime = DateTimeUtil.currentSeconds() + 1; // adding 1 second to current time to avoid exact match

            LOGGER.info("qualifying slo cycles... " + currentTime);

            if (index.get() >= items.size())
            {
                promise.complete();
            }
            else
            {
                var item = items.getJsonObject(index.get());

                var context = item.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

                var diff = switch (SLOConstants.SLOFrequency.valueOfName(context.getString(SLOProfile.SLO_FREQUENCY)))
                {
                    case WEEKLY -> TimeUnit.DAYS.toSeconds(7);
                    case MONTHLY -> TimeUnit.DAYS.toSeconds(30);
                    case QUARTERLY -> TimeUnit.DAYS.toSeconds(90);
                    default -> TimeUnit.DAYS.toSeconds(1); // default we will take daily
                };

                // means already one cycle is running in this SLO profile
                if (item.containsKey(SLOProfile.SLO_CYCLE_ID))
                {
                    var cycle = SLOCycleConfigStore.getStore().getItem(item.getLong(SLOProfile.SLO_CYCLE_ID));

                    if (cycle != null && !cycle.isEmpty() && cycle.containsKey(SLOCycle.SLO_CYCLE_END_TIME))
                    {
                        var endTime = cycle.getLong(SLOCycle.SLO_CYCLE_END_TIME);

                        if (endTime != null && endTime <= currentTime)
                        {
                            LOGGER.info(String.format("for slo profile %s end time %s is less than current time %s", item.getString(SLOProfile.SLO_PROFILE_NAME), endTime, currentTime));

                            // end the current cycle
                            endCycle(item, cycle, cyclesToEnd);

                            if (item.getString(SLOProfile.SLO_PROFILE_STATE).equalsIgnoreCase(YES))
                            {
                                // skip the past cycles
                                while (endTime + diff <= currentTime)
                                {
                                    LOGGER.info(String.format("skipping past cycle for slo profile %s as end time %s is less than current time %s", item.getString(SLOProfile.SLO_PROFILE_NAME), endTime, currentTime));

                                    endTime += diff;
                                }

                                LOGGER.info(String.format("restarting new cycle for slo profile %s", item.getString(SLOProfile.SLO_PROFILE_NAME)));

                                startCycle(item, endTime, endTime + diff, cyclesToStart).onComplete(result->
                                {
                                    index.incrementAndGet();

                                    qualifyCycles(items, cyclesToEnd, cyclesToStart, index, promise);
                                });
                            }
                            else
                            {
                                LOGGER.info(String.format("not starting new cycle for slo profile %s as it is disabled", item.getString(SLOProfile.SLO_PROFILE_NAME)));

                                index.incrementAndGet();

                                qualifyCycles(items, cyclesToEnd, cyclesToStart, index, promise);
                            }
                        }
                        else
                        {
                            LOGGER.info(String.format("not restarting new cycle for slo profile %s as end time %s is greater than current time %s", item.getString(SLOProfile.SLO_PROFILE_NAME), endTime, currentTime));

                            index.incrementAndGet();

                            qualifyCycles(items, cyclesToEnd, cyclesToStart, index, promise);
                        }
                    }
                }
                // means SLO profile is not having any cycle started yet
                else
                {
                    var startTime = item.getLong(SLOProfile.SLO_PROFILE_START_TIME);

                    if (startTime <= currentTime)
                    {
                        LOGGER.info(String.format("for slo profile %s start time %s is less than current time %s", item.getString(SLOProfile.SLO_PROFILE_NAME), startTime, currentTime));

                        LOGGER.info(String.format("starting new cycle for slo profile %s", item.getString(SLOProfile.SLO_PROFILE_NAME)));

                        // start a new cycle
                        startCycle(item, startTime, startTime + diff, cyclesToStart).onComplete(result->
                        {
                            index.incrementAndGet();

                            qualifyCycles(items, cyclesToEnd, cyclesToStart, index, promise);
                        });
                    }
                    else
                    {
                        LOGGER.info(String.format("not starting new cycle for slo profile %s as start time %s is greater than current time %s", item.getString(SLOProfile.SLO_PROFILE_NAME), startTime, currentTime));

                        index.incrementAndGet();

                        qualifyCycles(items, cyclesToEnd, cyclesToStart, index, promise);
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Starts a new SLO cycle for the given profile.
     * Creates cycle configuration, resolves entities, and persists to database.
     *
     * @param sloProfile the SLO profile configuration
     * @param startTime the cycle start time
     * @param endTime the cycle end time
     * @param cyclesToStart the array to add the new cycle start event
     * @return a future that completes when the cycle is started
     */
    private Future<Void> startCycle(JsonObject sloProfile, long startTime, long endTime, JsonArray cyclesToStart)
    {
        var promise = Promise.<Void>promise();

        try
        {
            var sloId = sloProfile.getLong(ID);

            var cycleId = SLOCycleConfigStore.getStore().newId();

            var cycle = new JsonObject();

            var sloContext = sloProfile.getJsonObject(SLOProfile.SLO_PROFILE_CONTEXT);

            var duration = endTime - startTime;

            // resolve entities
            var entities = sloContext.containsKey(ENTITY_TYPE) && sloContext.getString(ENTITY_TYPE).equalsIgnoreCase(Tag.TAG)
                    ? ObjectConfigStore.getStore().getIdsByTags(sloContext.getJsonArray(ENTITIES))
                    : sloContext.containsKey(ENTITY_TYPE) && sloContext.getString(ENTITY_TYPE).equalsIgnoreCase(APIConstants.Entity.GROUP.getName())
                    ? ObjectConfigStore.getStore().getIdsByGroups(sloContext.getJsonArray(ENTITIES))
                    : ObjectConfigStore.getStore().getIds(sloContext.getJsonArray(ENTITIES));

            LOGGER.info(String.format("entities for slo profile %s are %s", sloProfile.getString(SLOProfile.SLO_PROFILE_NAME), entities));

            cycle.put(ID, cycleId)
                    .put(SLOCycle.SLO_CYCLE_NAME, sloProfile.getString(SLOProfile.SLO_PROFILE_NAME) + SPACE_SEPARATOR + DateTimeUtil.timestamp(startTime * 1000))
                    .put(SLOCycle.SLO_PROFILE_ID, sloId)
                    .put(SLOCycle.SLO_CYCLE_START_TIME, startTime)
                    .put(SLOCycle.SLO_CYCLE_END_TIME, endTime)
                    .put(SLOCycle.SLO_CYCLE_TOTAL_DURATION, duration)
                    .put(SLOCycle.SLO_CYCLE_NOTIFICATION_STATUS, SLOConstants.SLOStatus.OK.ordinal())
                    .put(SLOCycle.SLO_CYCLE_ACCEPTABLE_VIOLATION_TIME, duration - ((duration * sloContext.getInteger(SLOProfile.SLO_TARGET)) / 100))
                    .put(ENTITIES, entities);

            LOGGER.info(String.format("cycle : %s", cycle.encodePrettily()));

            sloProfile.put(SLOProfile.SLO_CYCLE_ID, cycleId);

            // update SLO profile
            Bootstrap.configDBService().update(DBConstants.TBL_SLO_PROFILE,
                    new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, sloId),
                    sloProfile, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                    {
                        if (result.succeeded())
                        {
                            SLOProfileConfigStore.getStore().updateItem(sloId).onComplete(asyncResult ->
                            {
                                if (asyncResult.succeeded())
                                {
                                    Bootstrap.configDBService().save(DBConstants.TBL_SLO_CYCLE,
                                            cycle, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, future ->
                                            {
                                                if (future.succeeded())
                                                {
                                                    SLOCycleConfigStore.getStore().addItem(future.result()).onComplete(asyncFuture ->
                                                    {
                                                        if (asyncFuture.succeeded())
                                                        {
                                                            try
                                                            {
                                                                // send notification to db
                                                                VisualizationConstants.sendCycleStartNotification(sloId.toString(), cycleId, startTime, LOGGER);

                                                                LOGGER.info(String.format("new cycle %s started for slo profile %s with start time %s and end time %s", cycleId, sloId, startTime, endTime));

                                                                // Register the newly started profile
                                                                var profile = SLOProfileConfigStore.getStore().getItem(sloId);

                                                                if (profile != null)
                                                                {
                                                                    registerSLOProfiles(new JsonArray().add(profile));

                                                                    cyclesToStart.add(new JsonObject()
                                                                            .put(EventBusConstants.EVENT_TYPE, SLOConstants.SLOEventType.SLO_CYCLE_START.getName())
                                                                            .put(SLOProfile.SLO_CYCLE_ID, cycleId)
                                                                            .put(SLOCycle.SLO_PROFILE_ID, sloId));

                                                                    // send the change notification to MetricPolicyInspector
                                                                    vertx.eventBus().publish(EventBusConstants.EVENT_CHANGE_NOTIFICATION, new JsonObject()
                                                                            .put(EventBusConstants.CHANGE_NOTIFICATION_TYPE, EventBusConstants.ChangeNotificationType.SLO_CYCLE_START)
                                                                            .put(SLOProfile.SLO_CYCLE_ID, cycleId)
                                                                            .put(SLOCycle.SLO_PROFILE_ID, sloId));
                                                                }

                                                                promise.complete();
                                                            }
                                                            catch (Exception exception)
                                                            {
                                                                LOGGER.error(exception);

                                                                promise.fail(exception);
                                                            }
                                                        }
                                                        else
                                                        {
                                                            LOGGER.error(asyncFuture.cause());

                                                            promise.fail(asyncFuture.cause());
                                                        }
                                                    });
                                                }
                                                else
                                                {
                                                    LOGGER.error(future.cause());

                                                    promise.fail(future.cause());
                                                }
                                            });
                                }
                                else
                                {
                                    LOGGER.error(asyncResult.cause());

                                    promise.fail(asyncResult.cause());
                                }
                            });
                        }
                        else
                        {
                            LOGGER.error(result.cause());

                            promise.fail(result.cause());
                        }
                    });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }

    /**
     * Ends an SLO cycle by adding it to the cycles to end array.
     *
     * @param sloProfile the SLO profile configuration
     * @param sloCycle the SLO cycle to end
     * @param cyclesToEnd the array to add the cycle end event
     */
    private void endCycle(JsonObject sloProfile, JsonObject sloCycle, JsonArray cyclesToEnd)
    {
        try
        {
            cyclesToEnd.add(new JsonObject()
                    .put(EventBusConstants.EVENT_TYPE, SLOConstants.SLOEventType.SLO_CYCLE_END.getName())
                    .put(SLOProfile.SLO_CYCLE_ID, sloCycle.getLong(ID))
                    .put(SLOCycle.SLO_PROFILE_ID, sloProfile.getLong(ID)));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ SLO Profile Registration related methods ------------------------ //

    /**
     * Registers SLO profiles for monitoring by sending init events and mapping entities.
     *
     * @param profiles the array of SLO profiles to register
     */
    private void registerSLOProfiles(JsonArray profiles)
    {
        try
        {
            for (var index = 0; index < profiles.size(); index++)
            {
                var profile = profiles.getJsonObject(index);

                if (profile != null && profile.containsKey(SLOProfile.SLO_CYCLE_ID))
                {
                    var cycle = SLOCycleConfigStore.getStore().getItem(profile.getLong(SLOProfile.SLO_CYCLE_ID));

                    if (cycle != null && !cycle.isEmpty())
                    {
                        // Send init event for this profile
                        vertx.eventBus().send(EventBusConstants.EVENT_SLO_UPDATE, new JsonObject()
                                .put(EventBusConstants.EVENT_TYPE, SLOConstants.SLOEventType.SLO_INIT.getName())
                                .put(SLOProfile.SLO_CYCLE_ID, profile.getLong(SLOProfile.SLO_CYCLE_ID))
                                .put(SLOCycle.SLO_PROFILE_ID, profile.getLong(ID))
                                .put(SLOProfile.SLO_PROFILE_TYPE, profile.getString(SLOProfile.SLO_PROFILE_TYPE)));

                        // Register profile mappings
                        assign(profile.getLong(ID), cycle.getJsonArray(ENTITIES), profile.getString(SLOProfile.SLO_PROFILE_TYPE));
                    }
                    else
                    {
                        LOGGER.warn(String.format("slo cycle %s not found for slo profile %s", 
                                profile.getLong(SLOProfile.SLO_CYCLE_ID), profile.getLong(ID)));
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Assigns entities to an SLO profile for monitoring by updating the internal mapping.
     *
     * @param profileId the SLO profile ID
     * @param entities the array of entity IDs to assign
     * @param sloTypeString the SLO type as string (AVAILABILITY or PERFORMANCE)
     */
    private void assign(long profileId, JsonArray entities, String sloTypeString)
    {
        try
        {
            // Convert string to SLOType enum using valueOfName
            var sloType = SLOConstants.SLOType.valueOfName(sloTypeString);

            for (var i = 0; i < entities.size(); i++)
            {
                var object = entities.getLong(i);

                // Get or create the type map for this object
                var types = sloProfilesByObject.computeIfAbsent(object, k -> new HashMap<>());

                // Get or create the profile list for this SLO type
                var profiles = types.computeIfAbsent(sloType, k -> new ArrayList<>());

                // Add the profile ID if not already present
                if (!profiles.contains(profileId))
                {
                    profiles.add(profileId);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    // ------------------------ DELETE_OBJECT event handling ------------------------ //

    /**
     * Handles object deletion events by sending appropriate SLO deletion events.
     * Processes both device-level and instance-level deletions.
     *
     * @param event the object deletion event
     */
    private void handleObjectDeletion(JsonObject event)
    {
        try
        {
            var objectId = event.getLong(ID);

            if (objectId == null)
            {
                LOGGER.warn("DELETE_SLO_PROFILE event received with null object id");

                return;
            }

            var instances = event.getJsonArray(NMSConstants.METRIC_INSTANCES);

            // Get all SLO profiles for this object
            var types = sloProfilesByObject.get(objectId);

            if (types != null)
            {
                // Process all SLO types (both AVAILABILITY and PERFORMANCE)
                for (var sloProfileIds : types.values())
                {
                    if (sloProfileIds != null && !sloProfileIds.isEmpty())
                    {
                        // For each affected SLO profile, send appropriate deletion event
                        for (var sloProfileId : sloProfileIds)
                        {
                            if (instances != null && !instances.isEmpty())
                            {
                                // Instance deletion event
                                vertx.eventBus().send(EventBusConstants.EVENT_SLO_UPDATE, new JsonObject()
                                        .put(EventBusConstants.EVENT_TYPE, SLOConstants.SLOEventType.SLO_INSTANCE_DELETE.getName())
                                        .put(SLOCycle.SLO_PROFILE_ID, sloProfileId)
                                        .put(ID, objectId)
                                        .put(NMSConstants.METRIC_INSTANCES, instances)
                                        .put(EventBusConstants.EVENT_TIMESTAMP, DateTimeUtil.currentSeconds()));

                                if (CommonUtil.debugEnabled())
                                {
                                    LOGGER.debug(String.format("Sent SLO_INSTANCE_DELETE event for instances %s of object %s to SLO profile %s", 
                                            instances, objectId, sloProfileId));
                                }
                            }
                            else
                            {
                                // Device deletion event
                                vertx.eventBus().send(EventBusConstants.EVENT_SLO_UPDATE, new JsonObject()
                                        .put(EventBusConstants.EVENT_TYPE, SLOConstants.SLOEventType.SLO_OBJECT_DELETE.getName())
                                        .put(SLOCycle.SLO_PROFILE_ID, sloProfileId)
                                        .put(ID, objectId)
                                        .put(EventBusConstants.EVENT_TIMESTAMP, DateTimeUtil.currentSeconds()));

                                if (CommonUtil.debugEnabled())
                                {
                                    LOGGER.debug(String.format("Sent SLO_DEVICE_DELETE event for object %s to SLO profile %s", 
                                            objectId, sloProfileId));
                                }
                            }
                        }
                    }
                }

                LOGGER.info(String.format("Processed DELETE_OBJECT event for object %s with instances %s", objectId, instances));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }
