package com.mindarray.store;

import com.mindarray.BootstrapMain;
import com.mindarray.GlobalConstants;
import com.mindarray.api.Configuration;
import com.mindarray.db.DBConstants;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import static com.mindarray.GlobalConstants.*;

public class ConfigurationConfigStore extends AbstractConfigStore
{
    private static final Logger LOGGER = new Logger(ConfigurationConfigStore.class, GlobalConstants.MOTADATA_STORE, "Configuration Config Store");

    private static final ConfigurationConfigStore STORE = new ConfigurationConfigStore();

    private final Map<Integer, Long> itemsByObjectId = new ConcurrentHashMap<>();

    private final Map<String, JsonArray> itemsByStatus = new ConcurrentHashMap<>();

    private final Map<String, JsonArray> itemsByDiscoveryStatus = new ConcurrentHashMap<>();

    private ConfigurationConfigStore()
    {
        super(DBConstants.COLLECTION_CONFIGURATION, LOGGER, false);
    }

    public static ConfigurationConfigStore getStore()
    {
        return STORE;
    }

    @Override
    public Future<Void> initStore()
    {
        var promise = Promise.<Void>promise();

        try
        {
            BootstrapMain.configDBService().getAll(DBConstants.COLLECTION_CONFIGURATION, result ->
            {
                if (result.succeeded())
                {
                    items.clear();

                    itemsByObjectId.clear();

                    itemsByStatus.clear();

                    itemsByDiscoveryStatus.clear();

                    if (result.result() != null && !result.result().isEmpty())
                    {
                        for (var index = 0; index < result.result().size(); index++)
                        {
                            var item = result.result().getJsonObject(index);

                            items.put(item.getLong(GlobalConstants.ID), item);

                            if (CommonUtil.debugEnabled())
                            {
                                LOGGER.debug(String.format("item added %s into the store", CommonUtil.removeSensitiveFields(item, false).encodePrettily()));
                            }

                            itemsByObjectId.put(item.getInteger(Configuration.CONFIG_OBJECT), item.getLong(ID));

                            if (item.containsKey(Configuration.CONFIG_MANAGEMENT_STATUS))
                            {
                                itemsByStatus.computeIfAbsent(item.getString(Configuration.CONFIG_MANAGEMENT_STATUS), val -> new JsonArray()).add(item.getInteger(Configuration.CONFIG_OBJECT));
                            }

                            if (item.containsKey(Configuration.CONFIG_LAST_DISCOVERY_STATUS))
                            {
                                // means successful discovery
                                itemsByDiscoveryStatus.computeIfAbsent(item.getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS), val -> new JsonArray()).add(item.getInteger(Configuration.CONFIG_OBJECT));
                            }
                        }
                    }

                    promise.complete();

                    LOGGER.info(String.format("store %s initialized...", this.getClass().getSimpleName()));
                }
                else
                {
                    LOGGER.fatal(String.format("failed to init store %s , reason : %s...", this.getClass().getSimpleName(), result.cause()));

                    promise.fail(result.cause());
                }
            });
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    @Override
    public Future<Void> addItem(long id)
    {
        return super.addItem(id).onComplete(handler ->
        {
            if (handler.succeeded())
            {
                itemsByObjectId.put(items.get(id).getInteger(Configuration.CONFIG_OBJECT), id);

                if (items.get(id).containsKey(Configuration.CONFIG_MANAGEMENT_STATUS))
                {
                    itemsByStatus.computeIfAbsent(items.get(id).getString(Configuration.CONFIG_MANAGEMENT_STATUS), val -> new JsonArray()).add(items.get(id).getInteger(Configuration.CONFIG_OBJECT));
                }

                if (items.get(id).containsKey(Configuration.CONFIG_LAST_DISCOVERY_STATUS))
                {
                    itemsByDiscoveryStatus.computeIfAbsent(items.get(id).getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS), val -> new JsonArray()).add(items.get(id).getInteger(Configuration.CONFIG_OBJECT));
                }
            }
        });
    }

    @Override
    public void deleteItem(long id)
    {
        itemsByObjectId.remove(items.get(id).getInteger(Configuration.CONFIG_OBJECT));

        itemsByStatus.get(items.get(id).getString(Configuration.CONFIG_MANAGEMENT_STATUS)).remove(items.get(id).getInteger(Configuration.CONFIG_OBJECT));

        itemsByDiscoveryStatus.get(items.get(id).getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS)).remove(items.get(id).getInteger(Configuration.CONFIG_OBJECT));

        super.deleteItem(id);
    }

    public Future<JsonObject> updateItem(long id, JsonObject object, String userName, String remoteAddress)
    {
        var promise = Promise.<JsonObject>promise();

        try
        {
            if (object != null && !object.isEmpty())
            {
                BootstrapMain.configDBService().update(DBConstants.COLLECTION_CONFIGURATION,
                        new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, id),
                        object, userName, remoteAddress,
                        future ->
                        {
                            if (future.succeeded() && !future.result().isEmpty())
                            {
                                super.updateItem(id).onComplete(handler -> {

                                    if (items.get(id).containsKey(Configuration.CONFIG_LAST_DISCOVERY_STATUS))
                                    {
                                        itemsByDiscoveryStatus.computeIfAbsent(items.get(id).getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS), val -> new JsonArray());

                                        if (!itemsByDiscoveryStatus.get(items.get(id).getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS)).contains(items.get(id).getInteger(Configuration.CONFIG_OBJECT)))
                                        {
                                            itemsByDiscoveryStatus.get(items.get(id).getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS)).add(items.get(id).getInteger(Configuration.CONFIG_OBJECT));
                                        }
                                    }
                                });

                                promise.complete(object);
                            }
                            else
                            {
                                promise.fail(future.cause().getMessage());
                            }
                        });
            }
            else
            {
                promise.complete(object);
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception.getMessage());
        }

        return promise.future();
    }

    public int getObjectId(long id)
    {
        return items.containsKey(id) ? CommonUtil.getInteger(items.get(id).getValue(Configuration.CONFIG_OBJECT)) : NOT_AVAILABLE;
    }

    public long getIdByObjectId(int id)
    {
        return itemsByObjectId.containsKey(id) ? itemsByObjectId.get(id) : NOT_AVAILABLE;
    }

    public JsonArray getItemsByObjectIds(JsonArray objectIds)
    {
        return new JsonArray(objectIds.stream().map(CommonUtil::getInteger).map(itemsByObjectId::get).toList());
    }

    public void updateItemStatus(long id, String status)
    {
        var managementStatus = status.equalsIgnoreCase(YES) ? NO : YES;

        if (itemsByStatus.containsKey(managementStatus))
        {
            //removing old entry
            itemsByStatus.get(managementStatus).remove(items.get(id).getInteger(Configuration.CONFIG_OBJECT));
        }

        itemsByStatus.computeIfAbsent(status, val -> new JsonArray()).add(items.get(id).getInteger(Configuration.CONFIG_OBJECT));
    }

    public JsonArray getItemsByStatus(String status, JsonArray objectIds)
    {
        return new JsonArray(itemsByStatus.get(status).stream().filter(objectIds::contains).distinct().toList());
    }

    public JsonArray getItemsByStatus(JsonArray ids, JsonArray categories, String status)
    {
        var objectIds = ObjectConfigStore.getStore().getObjectIdsByCategories(categories, ObjectConfigStore.getStore().getObjectIdsByIds(ids));

        if (objectIds != null && !objectIds.isEmpty())
        {
            var items = getItemsByStatus(status, objectIds);

            if (items != null && !items.isEmpty())
            {
                return getItems(getItemsByObjectIds(items));
            }
        }

        return null;
    }

    public JsonArray getItemsByDiscoveryStatus(JsonArray ids, JsonArray categories, String status)
    {
        var objectIds = ObjectConfigStore.getStore().getObjectIdsByCategories(categories, ids);

        if (objectIds != null && !objectIds.isEmpty())
        {
            if(status.equalsIgnoreCase(STATUS_SUCCEED))
            {
                var items = itemsByDiscoveryStatus.get(status);

                if (items != null && !items.isEmpty())
                {
                    return getItems(getItemsByObjectIds(items));
                }
            }
            else
            {
                return getItems(getItemsByObjectIds(objectIds));
            }
        }

        return null;
    }

    @Override
    public JsonArray flatItemsByMultipleValue(String field, JsonArray values, String flatField, String flatValue)
    {
        return new JsonArray(items.values().stream()
                .filter(item -> values.contains(item.getValue(field)) && item.getValue(flatField).equals(flatValue))
                .map(JsonObject::copy)
                .distinct().toList());
    }

    public JsonArray flatItemByMultipleValues(String field, JsonArray values, String flatField, String flatValue, String flatField2)
    {
        return new JsonArray(items.values().stream()
                .filter(item -> item.containsKey(field) && values.contains(item.getValue(field)) &&
                        item.containsKey(flatField) && item.getValue(flatField).equals(flatValue) &&
                        item.containsKey(flatField2))
                .map(JsonObject::copy)
                .distinct().toList());
    }

    // Count license which have success discovery status
    public int getProvisionedItems()
    {
        return items.values().parallelStream()
                .filter(item -> item.containsKey(Configuration.CONFIG_LAST_DISCOVERY_STATUS) && item.getString(Configuration.CONFIG_LAST_DISCOVERY_STATUS).equals(STATUS_SUCCEED))
                .toList().size();
    }
}

