                    ));

                }

                // Wait for all updates to complete
                Future.join(futures).onComplete(result ->
                {
                    if (result.succeeded())
                    {
                        LOGGER.info(String.format("successfully executed patch 8.0.26 - updated %d objects with template IDs", futures.size()));
                        promise.complete();
