        if (!ipAddresses.isEmpty())
        {
            if (Bootstrap.bootstrapType().equals(BootstrapType.AGENT))
            {
                ipAddress = ipAddresses.stream().filter(value -> value.equalsIgnoreCase(BootstrapAgent.getLocalAddress())).findFirst().orElseGet(ipAddresses::getFirst);
            }
            else
