            Assertions.assertEquals("ft-main-server.service", event.getString(TraceConstants.SERVICE_NAME));

            Assertions.assertTrue(event.containsKey(GlobalConstants.TIME_STAMP));

            Assertions.assertEquals(context.getLong(GlobalConstants.ID), event.getLong(GlobalConstants.ID));

            Assertions.assertNotNull(AgentCacheStore.getStore().getItem(event.getLong(GlobalConstants.ID)).getJsonObject("trace.ft-main-server.service"));

            Assertions.assertTrue(AgentCacheStore.getStore().getItem(event.getLong(GlobalConstants.ID)).getJsonObject("trace.ft-main-server.service").containsKey(TraceConstants.TRACE_LAST_INGESTION_TIMESTAMP));

            future.complete();
        });

