            if (MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.SECONDARY.name()) || MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.FAILOVER.name()))
            {
                vertx.eventBus().<Void>localConsumer(config().getString(EventBusConstants.EVENT_TYPE) + ".inactive",handler -> eventEngine.setStatus(false));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void runRetention(String eventType,long seconds)
    {
        try
        {
            var eventFiles = new File(CURRENT_DIR + PATH_SEPARATOR + EventBusConstants.EVENT_DIR + PATH_SEPARATOR + EventBusConstants.replace(eventType) + GlobalConstants.PATH_SEPARATOR + "event-files");

            if (eventFiles.exists())
            {
                var content = Files.readString(eventFiles.toPath(), StandardCharsets.UTF_8);

                if (!content.isEmpty())
                {
                    var events = new JsonArray(content);

                    LOGGER.info(String.format("%s file found in path : %s ",events.size(),eventFiles.getPath()));

                    for (var index = 0; index < events.size(); index++)
                    {
                        var timestamp = CommonUtil.getLong(events.getString(index));

                        var eventFile = new File(events.getString(index) + ".dat");

                        if (eventFile.exists() && timestamp < seconds)
                        {
                            vertx.eventBus().send(EVENT_DATASTORE_RETENTION_TRIGGER + DOT_SEPARATOR + eventType,CommonUtil.getLong(events.getString(index)));

                            LOGGER.info(String.format("event file ; %s qualified in retention",timestamp));
                        }
                    }
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    private void send(JsonObject event)
    {
        if (Bootstrap.bootstrapType() == BootstrapType.APP)
        {
            if (MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.STANDALONE.name()) || MotadataConfigUtil.getInstallationMode().equalsIgnoreCase(InstallationMode.PRIMARY.name()))
            {
                vertx.eventBus().send(EVENT_PUBLICATION_DATASTORE_WRITE, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,uuid).put(EVENT_TOPIC, DATASTORE_BROKER_OPERATION_TOPIC));

                LOGGER.trace(String.format("event sent to datastore %s ",uuid));
            }
            else
            {
                vertx.eventBus().send(EVENT_REMOTE, event.put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_UUID,uuid).put(RemoteEventProcessor.REMOTE_EVENT_PROCESSOR_INSTALLATION_MODE,MotadataConfigUtil.getInstallationMode()).put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.METRIC.getName()).put(EVENT_TYPE,EVENT_HA_DATASTORE_SECONDARY_SYNC));

                LOGGER.trace("datastore event sent to primary app");
            }
        }

        if (MotadataConfigUtil.devMode())
        {
            vertx.eventBus().send("test.datastore.metric",event);
        }
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        try
        {
            eventEngine.stop(vertx, promise);
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

