     * @param handler Handler to receive the first matching record or empty JsonObject if none found
     * @return This service instance for method chaining
     */
    @Override
    public ConfigDBService getOneByQuery(String table, JsonObject filter, Handler<AsyncResult<JsonObject>> handler)
    {
        get(table, filter, result ->
        {
            if (result.succeeded())
            {
                if (!result.result().isEmpty())
                {
                    handler.handle(Future.succeededFuture(result.result().getJsonObject(0)));
                }
                else
                {
                    handler.handle(Future.succeededFuture(new JsonObject()));
                }
            }
