package com.mindarray.api;

import com.mindarray.Bootstrap;
import com.mindarray.ErrorCodes;
import com.mindarray.ErrorMessageConstants;
import com.mindarray.GlobalConstants;
import com.mindarray.db.DBConstants;
import com.mindarray.eventbus.EventBusConstants;
import com.mindarray.nms.NMSConstants;
import com.mindarray.store.*;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import com.mindarray.visualization.VisualizationConstants;
import io.vertx.core.json.Json;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;
import io.vertx.ext.web.Router;
import io.vertx.ext.web.RoutingContext;
import org.apache.http.HttpStatus;

import java.util.stream.Collectors;

import static com.mindarray.ErrorMessageConstants.INTERNAL_SERVER_EXCEPTION;
import static com.mindarray.GlobalConstants.*;
import static com.mindarray.api.APIConstants.REQUEST_PARAM_TYPE;
import static com.mindarray.api.APIConstants.RESPONSE_CODE;
import static com.mindarray.eventbus.EventBusConstants.EVENT;
import static com.mindarray.eventbus.EventBusConstants.EVENT_TYPE;
import static org.apache.http.HttpStatus.SC_INTERNAL_SERVER_ERROR;

public class Misc extends AbstractAPI
{
    private static final Logger LOGGER = new Logger(Misc.class, MOTADATA_API, "Misc API");

    public Misc()
    {
        super("misc", MiscConfigStore.getStore(), LOGGER);
    }

    @Override
    public void init(Router router)
    {
        router.get("/models").handler(this::getModels);

        router.post("/column-mappers").handler(this::getColumnMappers);

        router.get("/object-tags").handler(this::getTags);

        router.get("/indexable-columns").handler(this::getIndexableColumns);

        router.get("/flow-interfaces").handler(this::getFlowInterfaces);

        router.get("/sources").handler((routingContext) -> send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, EventSourceConfigStore.getStore().getItemsByMultiValueField(EVENT_TYPE, routingContext.request().getParam("group.type")))));

        router.get("/vendors").handler((routingContext) -> send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, SNMPTrapVendorCacheStore.getStore().getItems())));

    }

    private void getModels(RoutingContext routingContext)
    {
        try
        {
            var filter = JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER)));

            if (filter != null && !filter.isEmpty())
            {
                //for topology plugin return make model based on vendor selection
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                        .put(GlobalConstants.RESULT, new JsonArray(SNMPDeviceCatalogConfigStore.getStore().flatMap().values().stream().filter(item -> filter.getString(AIOpsObject.OBJECT_VENDOR).equalsIgnoreCase(item.getString(SNMPDeviceCatalog.SNMP_DEVICE_CATALOG_VENDOR)))
                                .map(item -> item.getString(SNMPDeviceCatalog.SNMP_DEVICE_CATALOG_MODEL)).distinct().collect(Collectors.toList()))));
            }

            else
            {
                this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_BAD_REQUEST)
                        .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                        .put(GlobalConstants.MESSAGE, ErrorMessageConstants.API_INVALID_INPUT_PARAMETERS));
            }
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void getColumnMappers(RoutingContext routingContext)
    {
        try
        {
            var filter = routingContext.body().asJsonObject();

            Bootstrap.vertx().eventBus().<JsonObject>request(EventBusConstants.EVENT_COLUMN_MAPPER_QUERY, "", response ->
            {
                var event = response.result().body();

                if (response.succeeded())
                {
                    if (filter.getString(VisualizationConstants.VISUALIZATION_GROUP_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.METRIC.getName()))
                    {
                        var result = new JsonObject();

                        if (filter.containsKey(ENTITIES))
                        {
                            var pluginIds = MetricConfigStore.getStore().getMetricPluginsByObjects(filter.getJsonArray(ENTITIES));

                            for (var entry : event.getJsonObject(DBConstants.METRIC_COLUMNS).getMap().entrySet())
                            {
                                //disregard the motadata health agent counter and only use the health screen metrics. metrics starting with the name "motadata" should be used instead.

                                if (!entry.getKey().contains(((JsonObject) entry.getValue()).getString(DBConstants.MAPPER_INSTANCE) + VisualizationConstants.RESERVED_METRICS)
                                        && JsonObject.mapFrom(entry.getValue()).getJsonArray(DBConstants.MAPPER_PLUGIN_IDS).stream().anyMatch(pluginIds::contains))
                                {
                                    result.put(entry.getKey(), entry.getValue());
                                }
                            }
                        }
                        else
                        {

                            for (var entry : event.getJsonObject(DBConstants.METRIC_COLUMNS).getMap().entrySet())
                            {
                                //disregard the motadata health agent counter and only use the health screen metrics. metrics starting with the name "motadata" should be used instead.

                                if (!entry.getKey().contains(((JsonObject) entry.getValue()).getString(DBConstants.MAPPER_INSTANCE) + VisualizationConstants.RESERVED_METRICS) && !JsonObject.mapFrom(entry.getValue()).containsKey(DBConstants.MAPPER_DURATION))
                                {
                                    result.put(entry.getKey(), entry.getValue());
                                }
                            }
                        }

                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, result));
                    }
                    else if (filter.getString(VisualizationConstants.VISUALIZATION_GROUP_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.LOG.getName()))
                    {
                        //in log plugin id is always greater than DBConstants.PluginId.LOG_EVENT.ordinal() so loading that specific columns only which contains greater from 600000 or 499999
                        var result = new JsonObject();

                        for (var entry : event.getJsonObject(DBConstants.EVENT_COLUMNS).getMap().entrySet())
                        {
                            if (JsonObject.mapFrom(entry.getValue()).getJsonArray(DBConstants.MAPPER_PLUGIN_IDS).stream().map(CommonUtil::getInteger).anyMatch(id -> id > DBConstants.PluginId.LOG_EVENT.getName() || id == DBConstants.PluginId.GENERIC_LOG_EVENT.getName() || id == DBConstants.PluginId.LOG_EVENT_STAT.getName()))
                            {
                                result.put(entry.getKey(), entry.getValue());
                            }
                        }

                        result.remove(EVENT);

                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, result));
                    }
                    else if (filter.getString(VisualizationConstants.VISUALIZATION_GROUP_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.FLOW.getName()))
                    {
                        var result = new JsonObject();

                        for (var entry : event.getJsonObject(DBConstants.EVENT_COLUMNS).getMap().entrySet())
                        {
                            if (JsonObject.mapFrom(entry.getValue()).getJsonArray(DBConstants.MAPPER_PLUGIN_IDS).stream().map(CommonUtil::getInteger).anyMatch(id -> id == DBConstants.PluginId.FLOW_EVENT.getName()))
                            {
                                result.put(entry.getKey(), entry.getValue());
                            }
                        }

                        result.remove(EVENT);

                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, result));
                    }
                    else if (filter.getString(VisualizationConstants.VISUALIZATION_GROUP_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.AVAILABILITY.getName()))
                    {
                        var result = new JsonObject();

                        event.getJsonObject(DBConstants.METRIC_COLUMNS).getMap().forEach((key, value) ->
                        {

                            try
                            {

                                if (JsonObject.mapFrom(value).getString(DBConstants.MAPPER_STATUS).equalsIgnoreCase(YES))
                                {
                                    if (filter.getString(VisualizationConstants.VISUALIZATION_CATEGORY) != null && filter.getString(VisualizationConstants.VISUALIZATION_CATEGORY).equalsIgnoreCase(VisualizationConstants.VisualizationCategory.GAUGE.getName()))
                                    {
                                        for (StatusType statusType : StatusType.values())
                                        {

                                            var column = EMPTY_VALUE;

                                            if (key.contains(INSTANCE_SEPARATOR))
                                            {
                                                column = key.split(INSTANCE_SEPARATOR)[0] + INSTANCE_SEPARATOR + CommonUtil.getString(statusType).toLowerCase() + ".count";
                                            }

                                            else
                                            {

                                                column = key.split("\\.")[0] + "." + CommonUtil.getString(statusType).toLowerCase() + ".count";
                                            }

                                            if (!result.containsKey(column))
                                            {
                                                result.put(column, value);
                                            }
                                        }
                                    }
                                    else if (filter.getString(VisualizationConstants.VISUALIZATION_TYPE) != null && filter.getString(VisualizationConstants.VISUALIZATION_TYPE).equalsIgnoreCase("report"))
                                    {
                                        var column = EMPTY_VALUE;

                                        if (key.contains(INSTANCE_SEPARATOR))
                                        {
                                            var tokens = key.split(INSTANCE_SEPARATOR);

                                            column = tokens[0].toLowerCase();
                                        }
                                        else
                                        {
                                            column = APIConstants.Entity.OBJECT.getName().toLowerCase();
                                        }

                                        if (!result.containsKey(column))
                                        {
                                            result.put(column, value);
                                        }
                                    }
                                    else
                                    {

                                        for (StatusType statusType : StatusType.values())
                                        {

                                            var column = EMPTY_VALUE;

                                            try
                                            {

                                                if (key.contains(INSTANCE_SEPARATOR))
                                                {
                                                    var tokens = key.split(INSTANCE_SEPARATOR);

                                                    column = tokens[0] + INSTANCE_SEPARATOR + CommonUtil.getString(statusType).toLowerCase() + "time." + tokens[1].split("\\.")[1];

                                                }

                                                else
                                                {
                                                    var tokens = key.split("\\.");

                                                    column = tokens[0] + "." + CommonUtil.getString(statusType).toLowerCase() + "time." + tokens[2];

                                                }

                                                if (!result.containsKey(column))
                                                {
                                                    result.put(column, value);
                                                }
                                            }

                                            catch (Exception exception)
                                            {
                                                LOGGER.error(exception);
                                            }
                                        }
                                    }
                                }

                            }
                            catch (Exception ignored)
                            {

                            }
                        });


                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, result));
                    }
                    else if (filter.getString(VisualizationConstants.VISUALIZATION_GROUP_TYPE).equalsIgnoreCase(VisualizationConstants.VisualizationDataSource.TRAP.getName()))
                    {
                        var result = new JsonObject();

                        for (var entry : event.getJsonObject(DBConstants.EVENT_COLUMNS).getMap().entrySet())
                        {
                            if (JsonObject.mapFrom(entry.getValue()).getJsonArray(DBConstants.MAPPER_PLUGIN_IDS).stream().map(CommonUtil::getInteger).anyMatch(id -> id == DBConstants.PluginId.TRAP_EVENT.getName()))
                            {
                                result.put(entry.getKey(), entry.getValue());
                            }
                        }

                        result.remove(EVENT);

                        this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED)
                                .put(GlobalConstants.RESULT, result));
                    }

                }
                else
                {
                    this.send(routingContext, new JsonObject().put(RESPONSE_CODE, SC_INTERNAL_SERVER_ERROR)
                            .put(STATUS, GlobalConstants.STATUS_FAIL)
                            .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, response.cause().getMessage()))
                            .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                            .put(ERROR, CommonUtil.formatStackTrace(response.cause().getStackTrace())));
                }
            });
        }
        catch (Exception exception)
        {
            APIUtil.sendResponse(exception, routingContext);
        }
    }

    private void getTags(RoutingContext routingContext)
    {

        if (routingContext.request().getParam(FILTER) != null)
        {
            var requestParameters = JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER)));

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                    .put(GlobalConstants.RESULT, requestParameters.getString(REQUEST_PARAM_TYPE).equals(AIOpsObject.OBJECT_USER_TAGS) ? ObjectConfigStore.getStore().getUserTags() : ObjectConfigStore.getStore().getSystemTags()));

        }

        else
        {

            this.send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_SUCCEED)
                    .put(GlobalConstants.RESULT, ObjectConfigStore.getStore().getTags()));
        }
    }

    private void getFlowInterfaces(RoutingContext routingContext)
    {
        try
        {
            var items = new JsonObject();

            var ipAddresses = JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER))).getJsonArray(GlobalConstants.ENTITIES);

            for (var index = 0; index < ipAddresses.size(); index++)
            {
                var interfaces = MetricConfigStore.getStore().getNetworkInterfacesBySource(ipAddresses.getString(index));

                for (var interfaceIndex = 0; interfaceIndex < interfaces.size(); interfaceIndex++)
                {
                    var item = interfaces.getJsonObject(interfaceIndex);

                    items.put(item.getString(NMSConstants.INTERFACE_NAME) != null ?
                                    item.getString(NMSConstants.INTERFACE_NAME) + " (" + item.getString(NMSConstants.INTERFACE_INDEX) + ")" :
                                    item.getString(NMSConstants.INTERFACE_INDEX),
                            item.getString(NMSConstants.INTERFACE_INDEX));
                }
            }

            send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).put(GlobalConstants.RESULT, items));
        }

        catch (Exception exception)
        {
            LOGGER.error(exception);

            send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                    .put(ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()))
                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                    .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, exception.getMessage())));
        }
    }

    private void getIndexableColumns(RoutingContext routingContext)
    {
        try
        {
            Bootstrap.vertx().eventBus().<JsonObject>request(EventBusConstants.EVENT_INDEXABLE_COLUMN_QUERY, new JsonObject().put(PLUGIN_ID, JsonObject.mapFrom(Json.decodeValue(routingContext.request().getParam(FILTER))).getJsonArray(PLUGIN_ID)), result ->
                    send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_OK).put(GlobalConstants.STATUS, STATUS_SUCCEED).mergeIn(result.result().body())));

        }

        catch (Exception exception)
        {
            LOGGER.error(exception);

            send(routingContext, new JsonObject().put(RESPONSE_CODE, HttpStatus.SC_INTERNAL_SERVER_ERROR)
                    .put(GlobalConstants.STATUS, GlobalConstants.STATUS_FAIL)
                    .put(ERROR, CommonUtil.formatStackTrace(exception.getStackTrace()))
                    .put(ERROR_CODE, ErrorCodes.ERROR_CODE_INTERNAL_ERROR)
                    .put(MESSAGE, String.format(INTERNAL_SERVER_EXCEPTION, exception.getMessage())));
        }
    }
