package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.GlobalConstants;
import com.mindarray.api.Tag;
import com.mindarray.db.DBConstants;
import com.mindarray.policy.PolicyEngineConstants;
import com.mindarray.store.*;
import com.mindarray.util.Logger;
import io.vertx.core.Future;
import io.vertx.core.Promise;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.db.DBConstants.FIELD_NAME;
import static com.mindarray.policy.PolicyEngineConstants.POLICY_TAGS;

public class Patch8100 implements Patch
{
    private static final Logger LOGGER = new Logger(Patch8100.class, MOTADATA_PATCH, "Patch 8.1.00");

    private static final String VERSION = "8.1.00";

    @Override
    public String getVersion()
    {
        return VERSION;
    }

    @Override
    public Future<Void> doPatch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            LOGGER.info("executing 8.1.00 patch");

            patch().onComplete(result ->
            {
                if (result.succeeded())
                {
                    TagCacheStore.getStore().initStore().onComplete(asyncResult ->
                    {
                        if (asyncResult.succeeded())
                        {
                            LOGGER.info("successfully executed 8.1.00 patch");

                            promise.complete();
                        }
                        else
                        {
                            LOGGER.error(asyncResult.cause());

                            promise.fail(asyncResult.cause());
                        }
                    });
                }
                else
                {
                    LOGGER.error(result.cause());

                    promise.fail(result.cause());
                }
            });

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }


    /**
     * Executes the patch logic for updating policy config stores with resolved tags.
     * Iterates through Metric, Event, and NetRoute Policy Config Stores, updates their tag fields,
     * and persists the changes asynchronously.
     *
     * @return a Future that completes when all patch operations are done
     */
    private Future<Void> patch()
    {
        var promise = Promise.<Void>promise();

        try
        {
            var futures = new ArrayList<Future<Void>>();

            //Refactor resolve tags in Metric Policy Config Store
            var items = MetricPolicyConfigStore.getStore().getItems();

            if (items != null && !items.isEmpty())
            {
                LOGGER.info(String.format("executing patch for Metric Policy Config Store Items - found %d items", items.size()));

                for (var index = 0; index < items.size(); index++)
                {
                    try
                    {
                        var item = items.getJsonObject(index);

                        if (item.containsKey(PolicyEngineConstants.POLICY_TAGS) && item.getJsonArray(PolicyEngineConstants.POLICY_TAGS) != null && !item.getJsonArray(PolicyEngineConstants.POLICY_TAGS).isEmpty())
                        {
                            item.put(PolicyEngineConstants.POLICY_TAGS, TagConfigStore.getStore().addItems(item.getJsonArray(POLICY_TAGS), Tag.TagType.POLICY.getName(), DBConstants.ENTITY_TYPE_USER));

                            var future = Promise.<Void>promise();

                            futures.add(future.future());

                            Bootstrap.configDBService().update(DBConstants.TBL_METRIC_POLICY, new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, item.getLong(ID)),
                                    item, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                                    {
                                        try
                                        {
                                            if (result.succeeded())
                                            {
                                                MetricPolicyConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult ->
                                                {
                                                    if (asyncResult.succeeded())
                                                    {
                                                        LOGGER.info(String.format("Successfully updated metric policy config store  %s", item.getString(PolicyEngineConstants.POLICY_NAME, EMPTY_VALUE)));

                                                        future.complete();
                                                    }
                                                    else
                                                    {
                                                        LOGGER.warn(String.format("Unable to update metric policy config store item %s with reason %s", item.encode(), asyncResult.cause().getMessage()));

                                                        future.fail(asyncResult.cause().getMessage());
                                                    }
                                                });
                                            }
                                            else
                                            {
                                                LOGGER.warn(String.format("Unable to update metric policy config store item %s with reason %s", item.encode(), result.cause().getMessage()));

                                                future.fail(result.cause().getMessage());
                                            }
                                        }
                                        catch (Exception exception)
                                        {
                                            LOGGER.error(exception);

                                            future.fail(exception.getMessage());
                                        }
                                    });
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }
            }
            else
            {
                LOGGER.info("No items found in Metric Policy Config Store or store is empty");
            }

            items = EventPolicyConfigStore.getStore().getItems();

            if (items != null && !items.isEmpty())
            {
                LOGGER.info(String.format("executing patch for Event Policy Config Store Items - found %d items", items.size()));

                for (var index = 0; index < items.size(); index++)
                {
                    try
                    {
                        var item = items.getJsonObject(index);

                        if (item.containsKey(PolicyEngineConstants.POLICY_TAGS) && item.getJsonArray(PolicyEngineConstants.POLICY_TAGS) != null && !item.getJsonArray(PolicyEngineConstants.POLICY_TAGS).isEmpty())
                        {
                            item.put(PolicyEngineConstants.POLICY_TAGS, TagConfigStore.getStore().addItems(item.getJsonArray(PolicyEngineConstants.POLICY_TAGS), Tag.TagType.POLICY.getName(), DBConstants.ENTITY_TYPE_USER));

                            var future = Promise.<Void>promise();

                            futures.add(future.future());

                            Bootstrap.configDBService().update(DBConstants.TBL_EVENT_POLICY, new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, item.getLong(ID)),
                                    item, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                                    {
                                        try
                                        {
                                            if (result.succeeded())
                                            {
                                                EventPolicyConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult ->
                                                {
                                                    if (asyncResult.succeeded())
                                                    {
                                                        LOGGER.info(String.format("Successfully updated event policy config store %s", item.getString(PolicyEngineConstants.POLICY_NAME, EMPTY_VALUE)));

                                                        future.complete();
                                                    }
                                                    else
                                                    {
                                                        LOGGER.warn(String.format("Unable to update event policy config store item %s with reason %s", item.encode(), asyncResult.cause().getMessage()));

                                                        future.fail(asyncResult.cause().getMessage());
                                                    }
                                                });
                                            }
                                            else
                                            {
                                                LOGGER.warn(String.format("Unable to update event policy config store item %s with reason %s", item.encode(), result.cause().getMessage()));

                                                future.fail(result.cause().getMessage());
                                            }
                                        }
                                        catch (Exception exception)
                                        {
                                            LOGGER.error(exception);

                                            future.fail(exception.getMessage());
                                        }
                                    });
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }
            }
            else
            {
                LOGGER.info("No items found in Event Policy Config Store or store is empty");
            }

            items = NetRoutePolicyConfigStore.getStore().getItems();

            if (items != null && !items.isEmpty())
            {
                LOGGER.info(String.format("executing patch for Netroute Policy Config Store Items - found %d items", items.size()));

                for (var index = 0; index < items.size(); index++)
                {
                    try
                    {
                        var item = items.getJsonObject(index);

                        if (item.containsKey(PolicyEngineConstants.POLICY_TAGS) && item.getJsonArray(PolicyEngineConstants.POLICY_TAGS) != null && !item.getJsonArray(PolicyEngineConstants.POLICY_TAGS).isEmpty())
                        {
                            item.put(PolicyEngineConstants.POLICY_TAGS, TagConfigStore.getStore().addItems(item.getJsonArray(PolicyEngineConstants.POLICY_TAGS), Tag.TagType.POLICY.getName(), DBConstants.ENTITY_TYPE_USER));

                            var future = Promise.<Void>promise();

                            futures.add(future.future());

                            Bootstrap.configDBService().update(DBConstants.TBL_NETROUTE_POLICY, new JsonObject().put(FIELD_NAME, GlobalConstants.ID).put(VALUE, item.getLong(ID)),
                                    item, DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, result ->
                                    {
                                        try
                                        {
                                            if (result.succeeded())
                                            {
                                                NetRoutePolicyConfigStore.getStore().updateItem(item.getLong(ID)).onComplete(asyncResult ->
                                                {
                                                    if (asyncResult.succeeded())
                                                    {
                                                        LOGGER.info(String.format("Successfully updated NetRoute Policy Config Store %s", item.getString(PolicyEngineConstants.POLICY_NAME, EMPTY_VALUE)));

                                                        future.complete();
                                                    }
                                                    else
                                                    {
                                                        LOGGER.warn(String.format("Unable to update NetRoute Policy Config Store item %s with reason %s", item.encode(), asyncResult.cause().getMessage()));

                                                        future.fail(asyncResult.cause().getMessage());
                                                    }
                                                });
                                            }
                                            else
                                            {
                                                LOGGER.warn(String.format("Unable to update NetRoute Policy Config Store item %s with reason %s", item.encode(), result.cause().getMessage()));

                                                future.fail(result.cause().getMessage());
                                            }
                                        }
                                        catch (Exception exception)
                                        {
                                            LOGGER.error(exception);

                                            future.fail(exception.getMessage());
                                        }
                                    });
                        }
                    }
                    catch (Exception exception)
                    {
                        LOGGER.error(exception);
                    }
                }
            }
            else
            {
                LOGGER.info("No items found in NetRoute Policy Config Store or store is empty");
            }

            if (futures.isEmpty())
            {
                LOGGER.info("No policy items with tags found to migrate");

                promise.complete();
            }
            else
            {
                Future.join(futures).onComplete(result ->
                {
                    if (result.succeeded())
                    {
                        LOGGER.info(String.format("Successfully processed %d policy items with tags", futures.size()));

                        promise.complete();
                    }
                    else
                    {
                        LOGGER.error(result.cause());

                        promise.fail(result.cause());
                    }
                });
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);

            promise.fail(exception);
        }

        return promise.future();
    }
}

