import static com.mindarray.eventbus.EventBusConstants.*;
import static com.mindarray.policy.PolicyEngineConstants.POLICY_ID;
import static com.mindarray.policy.PolicyEngineConstants.POLICY_NAME;

/**
 * TraceProcessor is responsible for processing and dumping span, trace and root span data into db.
 * Key responsibilities:
 * - Process Trace and its spans, root spans
 * - dump spans into TRACE_SPAN plugin
 * - dump trace into TRACE plugin
 * - dump root span into TRACE_ROOT_SPAN
 */
public class TraceProcessor extends AbstractVerticle
{
    private static final Logger LOGGER = new Logger(TraceProcessor.class, GlobalConstants.MOTADATA_TRACE, "Trace Processor");
    private final JsonObject event = new JsonObject();
    private final JsonObject traceEvent = new JsonObject();
    private final JsonObject rootSpanEvent = new JsonObject();
    private final Map<String, Set<String>> spansByTrace = new HashMap<>(); // key -> trace.id, value -> set of span with parent id (separated by _)
    private final Map<String, Set<String>> tracesByRootSpan = new HashMap<>(); // key -> root span name, value -> set of trace ids
    private final Map<String, String> rootSpanByTrace = new HashMap<>(); // key -> trace.id, value -> root span name
    private final Map<String, Long> startTimeByTrace = new HashMap<>(); // key -> trace.id, value -> start time
    private final Map<String, Long> endTimeByTrace = new HashMap<>(); // key -> trace.id, value -> end time
    private final Set<String> tracesWithError = new HashSet<>(); // set of traces with error
    private final Map<String, Integer> errorSpansByTrace = new HashMap<>();
    private final Map<String, Long> durationByTrace = new HashMap<>(); // key -> trace.id , value -> duration (nano)
    private final Map<String, String> serviceByTrace = new HashMap<>(); // key -> trace.id , value -> service name
    private final Map<String, Set<String>> entitiesByService = new HashMap<>(); // Note - Don't add this map in clear method
    private final Map<String, Set<String>> entitiesByTraces = new HashMap<>();
    private final Map<String, Integer> eventsByService = new HashMap<>();
    private final Map<String, Integer> traceVolumeByService = new HashMap<>();
    private final Map<String, Integer> spanVolumeByService = new HashMap<>();
    private final Map<String, Integer> spansByService = new HashMap<>();
    private final Map<String, Integer> maxSpansByTrace = new HashMap<>();
    private final Map<String, Set<String>> traceByEntity = new HashMap<>(); // key -> span.getName() + SEPARATOR + entity , value -> Trace ids
    private final JsonObject statsByService = new JsonObject();
    private final JsonObject entityStatsByService = new JsonObject(); // key -> serviceName``||``objectId``||``agentType``||``span name , value -> Entity stats
    private final StringBuilder builder = new StringBuilder();
    private final StringBuilder stackBuilder = new StringBuilder(); // Used for trimming span error stacktrace
    private EventEngine eventEngine;
    private Set<String> mappers;

    /**
     * Policy engine for handling event qualification and aggregation
     */
    private final PolicyEngine policyEngine;

    public TraceProcessor()
    {
        this.policyEngine = new PolicyEngine(PolicyEngineConstants.PolicyType.TRACE_ANALYTICS.getName());
    }

    @Override
    public void start(Promise<Void> promise) throws Exception
    {
        mappers = new HashSet<>();

        var items = EventSourceConfigStore.getStore().flatItemsByValue(EventBusConstants.EVENT_TYPE, VisualizationConstants.VisualizationDataSource.TRACE_SPAN.getName(), EVENT_SOURCE);

        // Process each event source
        if (items != null && !items.isEmpty())
        {
            for (var index = 0; index < items.size(); index++)
            {
                var source = items.getJsonObject(index);

                // Add new source if not already registered
                if (!TraceCacheStore.getStore().getSources().contains(source.getString(EVENT_SOURCE)))
                {
                    TraceCacheStore.getStore().addSource(items.getJsonObject(index).getString(EVENT_SOURCE));

                    // Update plugin configuration for this source
                    var id = ObjectConfigStore.getStore().getItemByIP(items.getJsonObject(index).getString(EVENT_SOURCE));

                    if (id != null)
                    {
                        ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_METRIC.getName(), id);

                        ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_JVM_MEMORY_METRIC.getName(), id);

                        ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_JVM_GC_METRIC.getName(), id);

                        ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_JVM_THREAD_METRIC.getName(), id);

                        ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_JVM_CLASS_METRIC.getName(), id);

                        ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_ENTITY_METRIC.getName(), id);
                    }
                }
            }
        }

        vertx.eventBus().<JsonObject>localConsumer(EVENT_CHANGE_NOTIFICATION, message ->
        {
            var event = message.body();

            switch (ChangeNotificationType.valueOf(event.getString(CHANGE_NOTIFICATION_TYPE)))
            {
                case ADD_POLICY, UPDATE_POLICY ->
                {
                    var policy = EventPolicyConfigStore.getStore().getItem(event.getLong(ID));

                    if(policy!= null && policyEngine.isApplicablePolicy(policy))
                    {
                        policyEngine.addPolicy(policy);
                    }
                }

                case DELETE_POLICY ->
                {
                    policyEngine.removePolicy(event.getLong(ID));
                }

                case SUPPRESS_POLICY ->
                {
                    if (message.body() != null)
                    {
                        policyEngine.suppressPolicy(event.getLong(POLICY_ID), true);
                    }
                }

                case UNSUPPRESS_POLICY ->
                {
                    if (message.body() != null)
                    {
                        policyEngine.suppressPolicy(event.getLong(POLICY_ID), false);
                    }
                }

                case DISABLE_POLICY_ACTION_TRIGGER ->
                {
                    var item = SchedulerConfigStore.getStore().getItem(event.getLong(ID));

                    if (item != null)
                    {
                        Bootstrap.configDBService().delete(DBConstants.TBL_SCHEDULER, new JsonObject().put(DBConstants.FIELD_NAME, ID).put(VALUE, event.getLong(ID)), DEFAULT_USER, SYSTEM_REMOTE_ADDRESS, future ->
                        {
                            if (future.succeeded())
                            {
                                SchedulerConfigStore.getStore().deleteItem(event.getLong(ID));

                                JobScheduler.removeJob(event.getLong(ID));
                            }
                        });
                    }
                }
                default ->
                {
                    // do nothing
                }
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>request(EventBusConstants.EVENT_EVENT_COLUMN_MAPPER_QUERY, EMPTY_VALUE, reply ->
        {
            try
            {
                var item = reply.result();

                if (item != null && item.body() != null)
                {
                    // Initialize the policy engine with event columns and policies
                    policyEngine.initialize(item.body().getJsonObject(DatastoreConstants.EVENT_COLUMNS), EventPolicyConfigStore.getStore().getItems());
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        });

        vertx.eventBus().<JsonObject>localConsumer(EventBusConstants.EVENT_COLUMN_MAPPER_UPDATE, message ->
        {
            try
            {
                var event = message.body();

                var tokens = event.getString(DatastoreConstants.MAPPER).split(GlobalConstants.COLUMN_SEPARATOR, -1);

                if (event.getString(CHANGE_NOTIFICATION_TYPE).equalsIgnoreCase(EventBusConstants.ChangeNotificationType.UPDATE_EVENT_COLUMN.name()))
                {
                    policyEngine.updateEventColumns(tokens);
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }
        }).exceptionHandler(LOGGER::error);

        vertx.eventBus().<JsonObject>localConsumer(EVENT_EVENT_POLICY_SUPPRESS, message ->
                message.reply(message.body() != null && policyEngine.isPolicySuppressed(message.body().getLong(POLICY_ID))));

        // Registers a local consumer to handle policy stats fetch requests.
        // This is triggered by the EventPolicyInspector to collect current group statistics
        // for a given policy ID. The collected stats are processed and sent back via event bus.
        vertx.eventBus().<Long>localConsumer(EVENT_EVENT_POLICY_AGGREGATOR_QUERY + DOT_SEPARATOR + PolicyEngineConstants.PolicyType.TRACE_ANALYTICS.getName(), message ->
        {
            try
            {
                var id = message.body();

                var item = new JsonObject().put(ID, id).put(RESULT, policyEngine.getPolicyStats(id)); //taking variable for logging purpose...

                message.reply(item);

                if(CommonUtil.debugEnabled())
                {
                    LOGGER.debug(EventPolicyConfigStore.getStore().getItem(id).getString(POLICY_NAME) + " :  " + item);
                }
            }
            catch (Exception exception)
            {
                LOGGER.error(exception);
            }

        });

        eventEngine = new EventEngine()
                .setLogger(LOGGER)
                .setEventType(config().getString(EventBusConstants.EVENT_TYPE))
                .setPersistEventOffset(true)
                .setEventQueueSize(MotadataConfigUtil.getTraceProcessorQueueSize())
                .setEventHandler(this::process)
                .start(vertx, promise);

        //broadcasting stats to stat calculator
        vertx.setPeriodic(60 * 1000, timer ->
        {
            vertx.eventBus().send(EVENT_TRACE_STAT, new JsonObject().put("service.stats", statsByService).put("service.entity.stats", entityStatsByService));

            statsByService.clear();

            entityStatsByService.clear();
        });

        promise.future().onComplete(result -> LOGGER.debug(config().getString(EVENT_TYPE) + " started successfully!!!"));
    }

    /**
     * Method will parse the trace data and will calculate the service, span, root span and trace level KPIs.
     * Sample JSON : {"resourceSpans":[{"resource":{"attributes":[{"key":"service.name","value":{"stringValue":"my.service"}}]},"scopeSpans":[{"scope":{"name":"my.library","version":"1.0.0"},"spans":[{"traceId":"5B8EFFF798038103D269B633813FC60C","spanId":"EEE19B7EC3C1B174","parentSpanId":"EEE19B7EC3C1B173","name":"I'm a server span","startTimeUnixNano":"1544712660000000000","endTimeUnixNano":"1544712661000000000","kind":2,"attributes":[{"key":"my.span.attr","value":{"stringValue":"some value"}}]}]}]}]}
     * @param message Trace Message
     */
    private void process(JsonObject message)
    {
        try
        {
            var context = TracesData.parseFrom(message.getBinary(EVENT));

            var eventSource =  message.getString(EVENT_SOURCE);

            var objectId = message.getInteger(AIOpsObject.OBJECT_ID);

            var agentId = message.getLong(ID);

            addEventSource(eventSource);

            var startTime = System.currentTimeMillis();

            for (var resourceSpan :  context.getResourceSpansList())
            {
                try
                {
                    var resource = resourceSpan.getResource();

                    var resourceAttribute = TraceConstants.parseAttribute(resource.getAttributesList(), stackBuilder);

                    var garbageAttributes = TraceCacheStore.getStore().getGarbageAttributes();

                    resourceAttribute.getMap().keySet().removeIf(garbageAttributes::contains);

                    var serviceName = CommonUtil.isNotNullOrEmpty(resourceAttribute.getString(TraceConstants.SERVICE_NAME)) ? resourceAttribute.getString(TraceConstants.SERVICE_NAME).trim() : TraceConstants.UNKNOWN_SERVICE;

                    traceVolumeByService.put(serviceName, traceVolumeByService.getOrDefault(serviceName, 0) + resourceSpan.getSerializedSize());

                    var serviceId = TraceServiceConfigStore.getStore().getIdByService(serviceName);

                    var agentType = TraceConstants.getAgentType(resourceAttribute);

                    var statsKey = String.format(TraceConstants.SERVICE_KEY, serviceName, objectId, agentType);

                    if (AgentCacheStore.getStore().getItem(agentId).getJsonObject(TraceConstants.TRACE_PREFIX + serviceName) == null)
                    {
                        var item = AgentCacheStore.getStore().getItem(agentId).put(TraceConstants.TRACE_PREFIX + serviceName, new JsonObject()
                                .put(TraceConstants.TRACE_LAST_INGESTION_TIMESTAMP, DateTimeUtil.currentSeconds()));

                        AgentCacheStore.getStore().updateItem(agentId, item);

                        LOGGER.debug(String.format("Received first trace for %s service", serviceName));

                        // when we receive first trace, we will send APM service registration request to UI.
                        publish(EVENT_SERVICE_TRACE_REGISTRATION, new JsonObject().put(TraceConstants.SERVICE_NAME, serviceName)
                                .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                .put(TraceConstants.SERVICE_TRACE_STATUS, "Active")
                                .put(ID, agentId)
                                .put(TraceConstants.SERVICE_TYPE, TraceConstants.AgentType.valueOfName(agentType)));
                    }
                    else
                    {
                        var item = AgentCacheStore.getStore().getItem(agentId).getJsonObject(TraceConstants.TRACE_PREFIX + serviceName);

                        item.put(TraceConstants.TRACE_LAST_INGESTION_TIMESTAMP, DateTimeUtil.currentSeconds());

                        AgentCacheStore.getStore().updateItem(agentId, AgentCacheStore.getStore().getItem(agentId).put(TraceConstants.TRACE_PREFIX + serviceName, item));
                    }

                    if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                    {
                        vertx.eventBus().send("trace.test", new JsonObject().put(TraceConstants.SERVICE_NAME, serviceName)
                                .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                .put(TraceConstants.TELEMETRY_SDK_LANGUAGE, resourceAttribute.getString(TraceConstants.TELEMETRY_SDK_LANGUAGE))
                                .put(ID, agentId));
                    }

                    preOperation(resourceSpan.getScopeSpansList());

                    for (var scopeSpan : resourceSpan.getScopeSpansList())
                    {
                        TraceCacheStore.getStore().subtract(scopeSpan.getSpansCount());

                        eventsByService.put(serviceName, eventsByService.getOrDefault(serviceName, 0) + scopeSpan.getSpansList().size());

                        spansByService.put(serviceName, spansByService.getOrDefault(serviceName, 0) + scopeSpan.getSpansList().size());

                        for (var span : scopeSpan.getSpansList())
                        {
                            this.event.clear();

                            spanVolumeByService.put(serviceName, spanVolumeByService.getOrDefault(serviceName, 0) + span.getSerializedSize());

                            var attributes = TraceConstants.parseAttribute(span.getAttributesList(), stackBuilder);

                            removeGarbage(attributes, garbageAttributes, this.event);

                            this.event.put(TraceConstants.SERVICE_SPAN_ID, TraceConstants.convertHex(span.getSpanId())).
                                    put(TraceConstants.SERVICE_SPAN_PARENT_ID, span.getParentSpanId().isEmpty() ? EMPTY_VALUE : TraceConstants.convertHex(span.getParentSpanId())).
                                    put(TraceConstants.SERVICE_SPAN_TRACE_ID, TraceConstants.convertHex(span.getTraceId())).
                                    put(TraceConstants.SERVICE_SPAN_SERVICE_NAME, serviceName).
                                    put(TraceConstants.SERVICE_SPAN_START_TIME_US, TraceConstants.convertTime(span.getStartTimeUnixNano(), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS)).
                                    put(TraceConstants.SERVICE_SPAN_DURATION_US, TraceConstants.convertTime(span.getEndTimeUnixNano() - span.getStartTimeUnixNano(), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS)).
                                    put(TraceConstants.SERVICE_SPAN_NAME, span.getName()).
                                    put(TraceConstants.SERVICE_SPAN_KIND, span.getKind().getNumber()).
                                    put(TraceConstants.SERVICE_SPAN_EXCEPTION_NAME, DASH_SEPARATOR).
                                    put(TraceConstants.SERVICE_SPAN_EVENT, processSpanEvents(span).encode()).
                                    put(TraceConstants.SERVICE_SPAN_STATUS_CODE, attributes.getString("http.response.status_code", DASH_SEPARATOR)).
                                    put(TraceConstants.SERVICE_SPAN_STATUS, span.getStatus().getCodeValue()).
                                    put(TraceConstants.SERVICE_SPAN_TOTAL_COUNT, maxSpansByTrace.get(this.event.getString(TraceConstants.SERVICE_SPAN_TRACE_ID))).
                                    put(TraceConstants.SERVICE_SPAN_HTTP_STATUS_CODE, CommonUtil.getInteger(attributes.getString("http.response.status_code", "0"))).
                                    put(PLUGIN_ID, DatastoreConstants.PluginId.TRACE_SPAN.getName()).
                                    put(EVENT_SOURCE, eventSource).
                                    put(EVENT_TIMESTAMP, TraceConstants.convertTime(span.getStartTimeUnixNano(), TimeUnit.NANOSECONDS, TimeUnit.SECONDS));

                            // Updating all the local maps which will be used to calculate kpis for root span, trace service etc.
                            update(span, agentType, attributes);

                            this.event.put(TraceConstants.SERVICE_SPAN_ATTRIBUTE_EVENT, TraceConstants.packEvent(this.event.getString(TraceConstants.SERVICE_SPAN_PARENT_ID).isEmpty() ? attributes.mergeIn(resourceAttribute).put("span.name", this.event.getString(TraceConstants.SERVICE_SPAN_NAME)) : attributes));

                            writeSpan(span);

                            if (serviceId != -1L)
                            {
                                policyEngine.processEvent(event.put(TraceConstants.SERVICE_ID, serviceId).put(TraceConstants.SERVICE_NAME, event.getString(TraceConstants.SERVICE_SPAN_SERVICE_NAME)));
                            }

                            if (span.getDroppedAttributesCount() > 0 || span.getDroppedEventsCount() > 0 || span.getDroppedLinksCount() > 0)
                            {
                                LOGGER.info(String.format("Dropped Attributes : %s , Dropped Events : %s, Dropped Links : %s", span.getDroppedAttributesCount(), span.getDroppedEventsCount(), span.getDroppedLinksCount()));
                            }
                        }
                    }

                    if (!spansByTrace.isEmpty())
                    {
                        for (var traceId : spansByTrace.keySet())
                        {
                            writeTrace(traceId, serviceName, eventSource, serviceId);
                        }

                        writeRootSpans(eventSource, serviceId, serviceName);

                        processServiceDependency(serviceName, eventSource, objectId, agentType);

                        updateServiceStats(statsKey, serviceName);

                        updateServiceEntityStats(statsKey);
                    }

                    if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
                    {
                        vertx.eventBus().send("trace.service.stats.test", new JsonObject().put(TraceConstants.SERVICE_NAME, serviceName)
                                .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                .put(TraceConstants.TELEMETRY_SDK_LANGUAGE, resourceAttribute.getString(TraceConstants.TELEMETRY_SDK_LANGUAGE))
                                .put("service.stats",new JsonObject().mergeIn(statsByService))
                                .put(ID, agentId));

                        vertx.eventBus().send("trace.service.entity.stats.test", new JsonObject().put(TraceConstants.SERVICE_NAME, serviceName)
                                .put(TIME_STAMP, DateTimeUtil.currentSeconds())
                                .put(TraceConstants.TELEMETRY_SDK_LANGUAGE, resourceAttribute.getString(TraceConstants.TELEMETRY_SDK_LANGUAGE))
                                .put("service.entity.stats",new JsonObject().mergeIn(entityStatsByService))
                                .put(ID, agentId));
                    }

                }
                catch (Exception exception)
                {
                    LOGGER.error(exception);
                }
                finally
                {
                    clear();
                }
            }

            LOGGER.debug(String.format("Trace Processor took %s (ms) to process the %s batch..", (System.currentTimeMillis() - startTime), TraceConstants.Type.TRACE.getName()));
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Filters and transfers span attributes to the event object, excluding specified garbage attributes.
     * The method processes each attribute from the source attributes object and copies valid ones
     * to the target event object with a "service.span." prefix.
     * <p>This method helps in:
     * <ul>
     *     <li>Cleaning up unnecessary or noisy attributes</li>
     *     <li>Standardizing attribute names with proper prefixing</li>
     *     <li>Reducing event payload size by excluding unwanted data</li>
     * </ul>
     *
     * @param attributes The source JsonObject containing all span attributes to be filtered
     * @param garbageAttributes Set of attribute names that should be excluded from the event
     * @param event The target JsonObject where filtered attributes will be stored with proper prefix
     */
    private void removeGarbage(JsonObject attributes, Set<String> garbageAttributes, JsonObject event)
    {
        for (var attribute : attributes.getMap().keySet())
        {
            if (!garbageAttributes.contains(attribute))
            {
                event.put(String.format("%s%s", "service.span.", attribute), CommonUtil.getString(attributes.getValue(attribute)));
            }
        }
    }

    /**
     * Determines whether a given span should be written to the datastore and writes it if applicable.
     * <p>
     * A span is written if:
     * <ul>
     *   <li>It has an error status (as defined in {@code TraceConstants.StatusCode.ERROR}).</li>
     *   <li>Otherwise, the span is written if the trace has not exceeded {@code MAX_SPAN_COUNT} or if the span
     *       does not have a valid parent ID (i.e., it is a root span).</li>
     * </ul>
     *
     * @param span        span
     */
    private void writeSpan(Span span)
    {
        if ((TraceConstants.TRACE_MAX_SPANS - spansByTrace.get(TraceConstants.convertHex(span.getTraceId())).size()) >= 0
                || TraceConstants.sample(event))
        {

            DatastoreConstants.write(event.put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                    .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.TRACE_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.TRACE_SPAN.getName(), mappers, builder);
        }
    }

    /**
     * Method will be used to update the even source and plugin metrics which will be used for the data security in the visualization
     * @param eventSource Event Source
     */
    private void addEventSource(String eventSource)
    {
        if (!TraceCacheStore.getStore().getSources().contains(eventSource))
