            TraceCacheStore.getStore().addSource(eventSource);

            var objectId = MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST) ? ObjectConfigStore.getStore().getItemByIP("172.16.8.135") : ObjectConfigStore.getStore().getItemByIP(eventSource);

            ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_METRIC.getName(), objectId);

            ObjectConfigStore.getStore().updateItemPlugin(DatastoreConstants.PluginId.TRACE_ENTITY_METRIC.getName(), objectId);

            vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION,
                    new JsonObject().put(EVENT_SOURCE, eventSource)
                            .put(EVENT, VisualizationConstants.VisualizationDataSource.TRACE.getName())
                            .put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_EVENT_SOURCE)
                            .put(PLUGIN_ID, DatastoreConstants.PluginId.TRACE.getName())
                            .put(LogEngineConstants.EVENT_CATEGORY, VisualizationConstants.VisualizationDataSource.TRACE.getName()));

            vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION,
                    new JsonObject().put(EVENT_SOURCE, eventSource)
                            .put(EVENT, VisualizationConstants.VisualizationDataSource.TRACE_ROOT_SPAN.getName())
                            .put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_EVENT_SOURCE)
                            .put(ENTITIES, new JsonArray().add(eventSource))
                            .put(PLUGIN_ID, DatastoreConstants.PluginId.TRACE_ROOT_SPAN.getName())
                            .put(LogEngineConstants.EVENT_CATEGORY, VisualizationConstants.VisualizationDataSource.TRACE_ROOT_SPAN.getName()));

            vertx.eventBus().send(EVENT_CHANGE_LOCAL_NOTIFICATION,
                    new JsonObject().put(EVENT_SOURCE, eventSource)
                            .put(EVENT, VisualizationConstants.VisualizationDataSource.TRACE_SPAN.getName())
                            .put(CHANGE_NOTIFICATION_TYPE, ChangeNotificationType.ADD_EVENT_SOURCE)
                            .put(ENTITIES, new JsonArray().add(eventSource))
                            .put(PLUGIN_ID, DatastoreConstants.PluginId.TRACE_SPAN.getName())
                            .put(LogEngineConstants.EVENT_CATEGORY, VisualizationConstants.VisualizationDataSource.TRACE_SPAN.getName()));
        }
    }


    /**
     * Processes and updates the service dependency mapping based on the entities associated with the service.
     * <p>
     * This method builds a unique service key using the provided service name, object ID, and agent type.
     * It checks if new entities (from traces) are associated with this service and, if found, sends a dependency
     * addition request via the Vert.x event bus for each new entity.
     * <p>
     * It ensures that redundant or already-recorded entity-service relationships are not processed again,
     * minimizing unnecessary communication and processing.
     *
     * @param serviceName the name of the service for which dependencies are to be processed
     * @param eventSource the source of the event used to create a unique service key
     * @param objectId    the object identifier (typically an internal unique ID representing the service)
     * @param agentType   the type of agent reporting the service (e.g., Java, Node.js, etc.)
     */
    private void processServiceDependency(String serviceName, String eventSource, int objectId, int agentType)
    {
        var key = String.format(TraceConstants.SERVICE_KEY, serviceName, objectId, agentType);

        if (!entitiesByTraces.isEmpty())
        {
            var entities = entitiesByTraces.values().stream().flatMap(Collection::stream).collect(Collectors.toSet());

            entitiesByService.computeIfAbsent(key, value -> new HashSet<>());

            entities.removeAll(entitiesByService.get(key));

            // Only sending dependency add request when, any new entity dependency come
            if(!entities.isEmpty())
            {
                LOGGER.debug(String.format("Sending request to add dependency for the service : %s , dependency : %s", serviceName, entities));

                entitiesByService.get(key).addAll(entities);

                entities.forEach(entity -> {

                    var request = new JsonObject().put(AIOpsConstants.DEPENDENCY_TYPE, AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName())
                            .put(AIOpsConstants.DEPENDENCY_SOURCE, String.format(TraceConstants.SERVICE_DEPENDENCY_KEY, eventSource, serviceName, agentType))
                            .put(AIOpsConstants.DEPENDENCY_OPERATION, AIOpsConstants.DependencyOperation.ADD_ENTITIES.getName())
                            .put(AIOpsConstants.DEPENDENCY_LEVEL, TraceConstants.getDependencyLevel(entity.split(HASH_SEPARATOR)[0]))
                            .put(TraceConstants.ENTITY, entity);

                    vertx.eventBus().send(EVENT_DEPENDENCY + DOT_SEPARATOR + AIOpsConstants.DependencyType.LOCAL_DOMAIN.getName(), request);
                });
            }

            if (MotadataConfigUtil.getEnvironmentType().equalsIgnoreCase(ENV_TEST))
            {
                Bootstrap.vertx().eventBus().send("test.service.entities", new JsonObject().put(TraceConstants.ENTITIES, new JsonArray(new ArrayList<>(entities))));
            }
        }
    }

    /**
     * Method will parse the span events and parse the attributes
     * Example : {"events":[{"timeUnixNano":"1581452773000000123","name":"event-with-attr","attributes":[{"key":"span-event-attr","value":{"stringValue":"span-event-attr-val"}}],"droppedAttributesCount":2},{"timeUnixNano":"1581452773000000123","name":"event","droppedAttributesCount":2}]}
     * @param span Span
     * @return Span Events Array
     */
    private JsonArray processSpanEvents(Span span)
    {
        var events = new JsonArray();

        try
        {
            for (var spanEvent : span.getEventsList())
            {
                if (spanEvent.getName().equalsIgnoreCase("exception"))
                {
                    for (var attribute : spanEvent.getAttributesList())
                    {
                        if (attribute.getKey().equals("exception.type"))
                        {
                            event.put(TraceConstants.SERVICE_SPAN_EXCEPTION_NAME, attribute.getValue().getStringValue());

                            break;
                        }
                    }
                }

                events.add(new JsonObject().put(TraceConstants.START_TIME_MS, TraceConstants.convertTime(spanEvent.getTimeUnixNano(), TimeUnit.NANOSECONDS, TimeUnit.MILLISECONDS)).
                        put(TraceConstants.NAME, spanEvent.getName()).
                        put(TraceConstants.ATTRIBUTES, TraceConstants.parseAttribute(spanEvent.getAttributesList(), stackBuilder)));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return events;
    }

    /**
     * Updates internal data structures and trace cache with details extracted from a span and its associated attributes.
     * <p>
     * This method performs the following key operations:
     * <ul>
     *     <li>Parses and converts the span start and end times from nanoseconds to microseconds.</li>
     *     <li>Extracts the trace ID and updates span relationships, root spans, services, and service types.</li>
     *     <li>Populates mappings for entity associations, trace timelines, and error tracking.</li>
     *     <li>Updates multiple in-memory caches to support downstream analytics like dependency mapping and context resolution.</li>
     *     <li>Handles parent-child span relationships and root span identification.</li>
     * </ul>
     *
     * @param span       the {@link JsonObject} representing the OTEL span containing timing and structural metadata
     * @param attributes the {@link JsonObject} containing additional span attributes like service type, entities, etc.
     */
    private void update(Span span, int agentType, JsonObject attributes)
    {
        try
        {
            var traceId = event.getString(TraceConstants.SERVICE_SPAN_TRACE_ID);

            var spanStartTime = TraceConstants.convertTime(span.getStartTimeUnixNano(), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS);

            var spanEndTime = TraceConstants.convertTime(span.getEndTimeUnixNano(), TimeUnit.NANOSECONDS, TimeUnit.MICROSECONDS);

            // Updating entities for the respective service
            if (!attributes.isEmpty())
            {
                var entities = TraceConstants.getEntity(attributes);

                if (!entities.isEmpty())
                {
                    entitiesByTraces.computeIfAbsent(traceId, value -> new HashSet<>()).addAll(entities);
                }

                for (var entity : entities)
                {
                    // Note - There will be a single entity type and value per span

                    attributes.put("service.span.entity", entity);

                    traceByEntity.computeIfAbsent(span.getName() + SEPARATOR + entity, value -> new HashSet<>()).add(traceId);
                }

            }

            if (CommonUtil.isNotNullOrEmpty(event.getString(TraceConstants.SERVICE_SPAN_PARENT_ID))) // parent span id exists....
            {
                spansByTrace.computeIfAbsent(traceId, value -> new HashSet<>()).add(event.getString(TraceConstants.SERVICE_SPAN_ID) + "_" + event.getString(TraceConstants.SERVICE_SPAN_PARENT_ID));
            }
            else
            {
                spansByTrace.computeIfAbsent(traceId, value -> new HashSet<>()).add(event.getString(TraceConstants.SERVICE_SPAN_ID));

                tracesByRootSpan.computeIfAbsent(event.getString(TraceConstants.SERVICE_SPAN_NAME), value -> new HashSet<>()).add(traceId);

                rootSpanByTrace.put(traceId, event.getString(TraceConstants.SERVICE_SPAN_NAME));

                serviceByTrace.put(traceId, event.getString(TraceConstants.SERVICE_SPAN_SERVICE_NAME));

                // find service type and update in cache
                TraceCacheStore.getStore().updateServiceType(event.getString(TraceConstants.SERVICE_SPAN_SERVICE_NAME), TraceConstants.getServiceType(attributes));
            }

            startTimeByTrace.putIfAbsent(traceId, spanStartTime);

            if (startTimeByTrace.get(traceId) > spanStartTime)
            {
                startTimeByTrace.put(traceId, spanStartTime);
            }

            endTimeByTrace.putIfAbsent(traceId, spanEndTime);

            if (endTimeByTrace.get(traceId) < spanEndTime)
            {
                endTimeByTrace.put(traceId, spanEndTime);
            }

            if (event.getInteger(TraceConstants.SERVICE_SPAN_STATUS) == Status.StatusCode.STATUS_CODE_ERROR.getNumber())
            {
                tracesWithError.add(traceId);

                var count = errorSpansByTrace.putIfAbsent(traceId, 1);

                errorSpansByTrace.put(traceId, count != null ? ++count : 1);
            }

            if (MotadataConfigUtil.distributedTracingEnabled())
            {
                // Updating cache which will be used to create service dependency map
                TraceCacheStore.getStore().updateSpansByService(event.getString(TraceConstants.SERVICE_SPAN_ID), String.format(TraceConstants.SERVICE_DEPENDENCY_KEY, event.getString(EVENT_SOURCE), event.getString(TraceConstants.SERVICE_SPAN_SERVICE_NAME), agentType));

                TraceCacheStore.getStore().updateTraceContext(event.getString(TraceConstants.SERVICE_SPAN_TRACE_ID), event.getString(TraceConstants.SERVICE_SPAN_ID), event.getString(TraceConstants.SERVICE_SPAN_PARENT_ID));

                TraceCacheStore.getStore().updateTraceExpiryTime(event.getString(TraceConstants.SERVICE_SPAN_TRACE_ID));
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Writes the trace to the database through the TRACE plugin.
     * It prepares and populates the traceEvent JSON with relevant metadata like duration,
     * spans, errors, and associated service information, and sends it to the appropriate datastore and event bus.
     *
     * @param traceId     Unique identifier for the trace
     * @param serviceName Name of the service associated with the trace
     * @param eventSource Source of the trace event (e.g., system, user action)
     * @param serviceId   ID of the service; if -1, the policy event is not triggered
     */
    private void writeTrace(String traceId, String serviceName, String eventSource, long serviceId)
    {
        if (rootSpanByTrace.containsKey(traceId)) eventsByService.put(serviceName, eventsByService.getOrDefault(serviceName, 0) + 1);

        traceEvent.clear();

        durationByTrace.putIfAbsent(traceId, GlobalConstants.DUMMY_ID);

        durationByTrace.put(traceId, endTimeByTrace.get(traceId) - startTimeByTrace.get(traceId));

        traceEvent.put(TraceConstants.SERVICE_TRACE_ID, traceId)
                .put(TraceConstants.SERVICE_TRACE_SERVICE_NAME, serviceName)
                .put(TraceConstants.SERVICE_TRACE_DURATION_US, durationByTrace.get(traceId))
                .put(TraceConstants.SERVICE_TRACE_START_TIME_US, startTimeByTrace.get(traceId))
                .put(TraceConstants.SERVICE_TRACE_SPANS, spansByTrace.get(traceId).isEmpty() ? 0 : spansByTrace.get(traceId).size())
                .put(TraceConstants.SERVICE_TRACE_ENTITIES, entitiesByTraces.get(traceId) != null ? entitiesByTraces.get(traceId).size() : 0)
                .put(TraceConstants.SERVICE_TRACE_SPAN_ERRORS, errorSpansByTrace.getOrDefault(traceId, 0))
                .put(TraceConstants.SERVICE_TRACE_ATTRIBUTE_EVENT, Buffer.buffer().getBytes())
                .put(TraceConstants.SERVICE_TRACE_ROOT_SPAN_NAME, rootSpanByTrace.get(traceId))
                .put(TraceConstants.SERVICE_TRACE_ERRORS, errorSpansByTrace.containsKey(traceId) ? 1 : 0)
                .put(EVENT_SOURCE, eventSource)
                .put(EventBusConstants.EVENT_TIMESTAMP, TraceConstants.convertTime(startTimeByTrace.get(traceId), TimeUnit.MICROSECONDS, TimeUnit.SECONDS));

        DatastoreConstants.write(traceEvent.put(PLUGIN_ID, DatastoreConstants.PluginId.TRACE.getName())
                .put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.TRACE_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.TRACE.getName(), mappers, builder);

        if (serviceId != -1L)
        {
            policyEngine.processEvent(traceEvent.put(TraceConstants.SERVICE_ID, serviceId).put(TraceConstants.SERVICE_NAME, traceEvent.getString(TraceConstants.SERVICE_TRACE_SERVICE_NAME)));
        }
    }

    /**
     * Writes root span data to the database using the TRACE_ROOT_SPAN plugin.
     * For each root span, it aggregates associated trace information such as
     * service name, duration, errors, number of spans, and related entities.
     * This data is then persisted to the datastore and optionally sent to
     * the event bus for policy evaluation if a valid service ID is provided.
     *
     * @param eventSource Source identifier for the event
     * @param serviceId   Service ID for which root span data is being recorded;
     *                    if -1, policy evaluation is skipped
     */
    private void writeRootSpans(String eventSource, long serviceId, String service)
    {
        if (!tracesByRootSpan.isEmpty())
        {
            tracesByRootSpan.forEach((rootSpan, traceIds) ->

                    traceIds.forEach(traceId -> {

                        eventsByService.put(service, eventsByService.getOrDefault(service, 0) + 1);

                        rootSpanEvent.clear();

                        rootSpanEvent.put(TraceConstants.SERVICE_ROOT_SPAN_NAME, rootSpan)
                                .put(TraceConstants.SERVICE_ROOT_SPAN_SERVICE_NAME, serviceByTrace.getOrDefault(traceId, TraceConstants.UNKNOWN_SERVICE))
                                .put(TraceConstants.SERVICE_ROOT_SPAN_TRACE_DURATION_US, durationByTrace.getOrDefault(traceId, GlobalConstants.DUMMY_ID))
                                .put(TraceConstants.SERVICE_ROOT_SPAN_ERRORS, errorSpansByTrace.getOrDefault(traceId, GlobalConstants.DUMMY_NUMERIC_VALUE))
                                .put(TraceConstants.SERVICE_ROOT_SPAN_TRACE_ID, traceId)
                                .put(TraceConstants.SERVICE_ROOT_SPANS, spansByTrace.containsKey(traceId) ? spansByTrace.get(traceId).size() : 0);

                        if (rootSpanEvent.getString(TraceConstants.SERVICE_ROOT_SPAN_NAME).isEmpty())
                        {
                            LOGGER.warn(String.format("Root span is empty for span %s", rootSpanEvent));
                        }

                        DatastoreConstants.write(rootSpanEvent.put(PLUGIN_ID, DatastoreConstants.PluginId.TRACE_ROOT_SPAN.getName())
                            .put(EVENT_SOURCE, eventSource)
                            .put(EVENT_TIMESTAMP, TraceConstants.convertTime(startTimeByTrace.get(traceId), TimeUnit.MICROSECONDS, TimeUnit.SECONDS))
                            .put(DATASTORE_CATEGORY, DatastoreConstants.DatastoreCategory.TRACE.getName())
                            .put(DatastoreConstants.DATASTORE_TYPE, DatastoreConstants.DatastoreType.TRACE_EVENT.ordinal()), VisualizationConstants.VisualizationDataSource.TRACE_ROOT_SPAN.getName(), mappers, builder);

                        if (serviceId != -1L)
                        {
                            policyEngine.processEvent(rootSpanEvent.put(TraceConstants.SERVICE_ID, serviceId).put(TraceConstants.SERVICE_NAME, rootSpanEvent.getString(TraceConstants.SERVICE_ROOT_SPAN_SERVICE_NAME)));
                        }
                    })
            );
        }
    }

    /**
     * Counts the total number of spans for each trace ID in the given JSON array of scope spans.
     * <p>
     * This method iterates through the provided {@code scopeSpans} array, extracts the spans from each scope,
     * and increments the count of spans associated with each {@code traceId}. The counts are stored in the
     * {@code spanCountByTrace} map.
     * </p>
     * @param scopeSpans scope spans
     */
    public void preOperation(List<ScopeSpans> scopeSpans)
    {
        try
        {
            for (var scopeSpan : scopeSpans)
            {
                for (var span : scopeSpan.getSpansList())
                {
                    var id = TraceConstants.convertHex(span.getTraceId());

                    maxSpansByTrace.put(id, maxSpansByTrace.getOrDefault(id, 0) + 1);
                }
            }
        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }
    }

    /**
     * Updates service-level statistics by aggregating trace metrics for a specific service.
     * <p>
     * This method computes and updates various service performance metrics including:
     * <ul>
     *   <li>Total number of traces processed</li>
     *   <li>Number of traces with errors</li>
     *   <li>Total events count</li>
     *   <li>Trace and span volume in bytes</li>
     *   <li>Total spans count</li>
     *   <li>Trace durations for percentile calculations</li>
     *   <li>Entity information associated with traces</li>
     * </ul>
     * The statistics are stored in the {@code statsByService} map using the provided stats key
     * and will be periodically flushed to the datastore by the TraceStatCalculator.
     * </p>
     *
     * @param statsKey    the unique key identifying the service statistics entry, typically formatted as
     *                    "service_name~object_id~agent_type" using {@link TraceConstants#SERVICE_KEY}
     * @param serviceName the name of the service for which statistics are being updated
     */
    private void updateServiceStats(String statsKey, String serviceName)
    {
        statsByService.getMap().computeIfAbsent(statsKey, val -> new JsonObject());

        var stats = statsByService.getJsonObject(statsKey);

        stats.put(TraceConstants.TRACES, stats.getInteger(TraceConstants.TRACES, 0) + rootSpanByTrace.size())
                .put(TraceConstants.TRACE_ERRORS, stats.getInteger(TraceConstants.TRACE_ERRORS, 0) + tracesWithError.size())
                .put(TraceConstants.EVENTS, stats.getInteger(TraceConstants.EVENTS, 0) + eventsByService.get(serviceName))
                .put(TraceConstants.TRACES_VOLUME_BYTES, stats.getLong(TraceConstants.TRACES_VOLUME_BYTES, 0L) + traceVolumeByService.get(serviceName))
                .put(TraceConstants.SPANS_VOLUME_BYTES, stats.getLong(TraceConstants.SPANS_VOLUME_BYTES, 0L) + spanVolumeByService.get(serviceName))
                .put(TraceConstants.SPANS, stats.getInteger(TraceConstants.SPANS, 0) + spansByService.get(serviceName))
                .put(TraceConstants.TRACE_DURATION, stats.getJsonArray(TraceConstants.TRACE_DURATION, new JsonArray()).addAll(new JsonArray(durationByTrace.keySet().stream().filter(rootSpanByTrace::containsKey).map(durationByTrace::get).collect(Collectors.toList()))))
        ;

    }

    /**
     * Updates entity-level statistics for traces associated with specific entities within a service.
     * <p>
     * This method processes entity-specific trace metrics by:
     * <ul>
     *   <li>Iterating through all entities that have associated traces</li>
     *   <li>Parsing entity information (type and value) from the entity key</li>
     *   <li>Computing trace counts, error counts, and durations for each entity</li>
     *   <li>Storing entity metadata (type and value) for visualization purposes</li>
     * </ul>
     * Entity keys are expected to be in the format "span_name~entity_type#entity_value".
     * The resulting statistics enable entity-level performance analysis and are used
     * for generating entity-specific dashboards and alerts.
     * </p>
     *
     * @param statsKey the base statistics key for the service, which will be extended with entity
     *                 information to create unique entity statistics keys in the format
     *                 "service_stats_key~entity_span_name"
     */
    private void updateServiceEntityStats(String statsKey)
    {
        if (!traceByEntity.isEmpty())
        {
            for (var entity : traceByEntity.keySet())
            {
                var tokens =  entity.split(SEPARATOR_WITH_ESCAPE);

                var entityStatsKey = statsKey + SEPARATOR + tokens[0];

                var entityTokens = tokens[1].split("#");

                entityStatsByService.getMap().computeIfAbsent(entityStatsKey, val -> new JsonObject());

                var entityStats = entityStatsByService.getJsonObject(entityStatsKey);

                var traces = traceByEntity.get(entity);

                entityStats.put(TraceConstants.TRACES, entityStats.getInteger(TraceConstants.TRACES, 0) + traces.size())
                        .put(TraceConstants.TRACE_ERRORS, entityStats.getInteger(TraceConstants.TRACE_ERRORS, 0) + tracesWithError.stream().filter(traces::contains).collect(Collectors.toSet()).size())
                        .put(TraceConstants.TRACE_ENTITY_TYPE, entityTokens[0])
                        .put(TraceConstants.TRACE_ENTITY_VALUE, entityTokens[1])
                        .put(TraceConstants.TRACE_DURATION, entityStats.getJsonArray(TraceConstants.TRACE_DURATION, new JsonArray()).addAll(new JsonArray(durationByTrace.keySet().stream().filter(traces::contains).map(durationByTrace::get).collect(Collectors.toList()))));
            }
        }
    }

    /**
     * Method will clear all the caches after processing one scope span
    */
    private void clear()
    {
        spansByTrace.clear();

        tracesByRootSpan.clear();

        rootSpanByTrace.clear();

        durationByTrace.clear();

        startTimeByTrace.clear();

        endTimeByTrace.clear();

        tracesWithError.clear();

        errorSpansByTrace.clear();

        entitiesByTraces.clear();

        serviceByTrace.clear();

        event.clear();

        traceEvent.clear();

        rootSpanEvent.clear();

        maxSpansByTrace.clear();

        eventsByService.clear();

        traceVolumeByService.clear();

        spanVolumeByService.clear();

        spansByService.clear();

        traceByEntity.clear();
    }

    @Override
    public void stop(Promise<Void> promise) throws Exception
    {
        eventEngine.stop(vertx, promise);
    }
