    public static void assertRediscoveryTestResult()
    {
        messageHandler = TestUtil.vertx().eventBus().localConsumer(EVENT_USER + TestUtil.getSessionId(), message ->
        {
            try
            {
                var event = message.body();

                var eventContext = CodecUtil.toJSONObject(event.getBinary(EVENT_CONTEXT));

                if (event.getString(EVENT_TYPE) != null)
                {
                    if (event.getString(EVENT_TYPE).equalsIgnoreCase(UI_NOTIFICATION_STREAMING_BROADCAST))
                    {
                        if (eventContext.getString(EVENT_STATE) != null && eventContext.getString(EVENT_STATE).equals(EVENT_STATE_COMPLETED) && eventContext.getJsonObject(EVENT_CONTEXT) != null
                                && eventContext.getJsonObject(EVENT_CONTEXT).containsKey(EVENT_SCHEDULER) && REDISCOVERY_ITEMS.containsKey(eventContext.getJsonObject(EVENT_CONTEXT).getLong(EVENT_SCHEDULER)))
                        {
                            var schedulerId = eventContext.getJsonObject(EVENT_CONTEXT).getLong(EVENT_SCHEDULER);

                            var context = REDISCOVERY_ITEMS.get(schedulerId);

                            var testContext = (VertxTestContext) context.getValue("test.context");

                            var object = context.getJsonObject("object");

                            var rerun = context.getBoolean("rerun.rediscovery", false);

                            LOGGER.info(String.format("Result Of Event :: %s and rerun is %s", eventContext.encode(), rerun));

                            if (eventContext.getString(STATUS).equalsIgnoreCase(STATUS_SUCCEED))
                            {
                                Assertions.assertTrue(Boolean.TRUE);

                                if ((object != null && object.isEmpty()) || context.getBoolean("auto.provision"))
                                {
                                    if (!rerun)
                                    {
                                        REDISCOVERY_ITEMS.remove(schedulerId);

                                        testContext.completeNow();
                                    }
                                    else
                                    {
                                        Bootstrap.vertx().eventBus().send(EventBusConstants.UI_ACTION_SCHEDULER_RUN, new JsonObject().put(SESSION_ID, TestUtil.getSessionId()).put(USER_NAME, DEFAULT_USER).put(ID, schedulerId));
