                    {
                        assertEquals(ErrorMessageConstants.REDISCOVERY_RUN_FAILED_ALREADY_RUNNING,
                                CodecUtil.toJSONObject(message.body().getBinary(EVENT_CONTEXT)).getString(MESSAGE));

