package com.mindarray.patch;

import com.mindarray.Bootstrap;
import com.mindarray.db.ConfigDBConstants;
import com.mindarray.policy.PolicyEngineConstants;
import com.mindarray.store.LDAPServerConfigStore;
import com.mindarray.store.MetricPolicyConfigStore;
import com.mindarray.store.RemoteEventProcessorConfigStore;
import com.mindarray.util.CommonUtil;
import com.mindarray.util.Logger;
import io.vertx.core.json.Json;
import io.vertx.core.json.JsonArray;
import io.vertx.core.json.JsonObject;

import java.util.ArrayList;
import java.util.HashSet;

import static com.mindarray.GlobalConstants.*;
import static com.mindarray.GlobalConstants.ID;
import static com.mindarray.api.MetricPolicy.*;
import static com.mindarray.db.ConfigDBConstants.FIELD_NAME;
import static com.mindarray.policy.PolicyEngineConstants.*;

public class Patch806 implements Patch
{
    private static final Logger LOGGER = new Logger(Patch806.class, MOTADATA_PATCH, "Patch 8.0.6");

    @Override
    public String getVersion()
    {
        return "8.0.6";
    }

    @Override
    public boolean doPatch()
    {
        var status = false;

        try
        {
            LOGGER.info("updating all existing policy context for notification and renotification");

            var policies = LDAPServerConfigStore.getStore().getItems();

            for (var index = 0; index < policies.size(); index++)
            {
                var policy = policies.getJsonObject(index);

                if (CommonUtil.traceEnabled())
                {
                    LOGGER.trace(String.format("updating policy context %s", policies.encode()));
                }

                Bootstrap.configDBService.update(ConfigDBConstants.COLLECTION_METRIC_POLICY,
                        new JsonObject().put(FIELD_NAME, ID).put(VALUE, policy.getLong(ID)),
                        updatePolicy(policy),
                        SYSTEM_USER, MOTADATA_SYSTEM, result ->
                        {
                            if (result.succeeded())
                            {
                                MetricPolicyConfigStore.getStore().updateItem(policy.getLong(ID)).onComplete(handler ->
                                {
                                    if (handler.succeeded())
                                    {
                                        LOGGER.info(String.format("updated policy : %s : item: %s", policy.getLong(ID), RemoteEventProcessorConfigStore.getStore().getItem(policy.getLong(ID))));
                                    }
                                    else
                                    {
                                        LOGGER.warn(handler.cause().getMessage());
                                    }
                                });
                            }
                            else
                            {
                                LOGGER.warn(String.format("failed to update remote event processor : %s ", policy.getLong(ID)));
                            }
                        });
            }

        }
        catch (Exception exception)
        {
            LOGGER.error(exception);
        }

        return status;
    }

    private JsonObject updatePolicy(JsonObject policy)
    {
        var emailRecipients = new HashSet<String>();

        var notifyContext = new JsonArray();

        var renotifyContext = new JsonArray();

        if (policy.containsKey(POLICY_EMAIL_NOTIFICATION_RECIPIENTS))
        {
            emailRecipients.addAll(policy.getJsonArray(POLICY_EMAIL_NOTIFICATION_RECIPIENTS).getList());

            policy.remove(POLICY_EMAIL_NOTIFICATION_RECIPIENTS);
        }

        if (policy.containsKey(POLICY_RENOTIFY) && policy.getString(POLICY_RENOTIFY).equalsIgnoreCase(NO))
        {
            renotifyContext.add(new JsonObject().put(POLICY_EMAIL_NOTIFICATION_RECIPIENTS, new JsonArray(new ArrayList(emailRecipients))).put(POLICY_USER_NOTIFICATION_RECIPIENTS, new JsonArray().add(SYSTEM_USER)).put(POLICY_NOTIFICATION_SEVERITY, Severity.CRITICAL.name()).put(POLICY_RENOTIFICATION_TIMER_SECONDS, 1800));
        }

        notifyContext.add(new JsonObject().put(POLICY_EMAIL_NOTIFICATION_RECIPIENTS, new JsonArray(new ArrayList(emailRecipients))).put(POLICY_USER_NOTIFICATION_RECIPIENTS, new JsonArray().add(SYSTEM_USER)).put(POLICY_NOTIFICATION_SEVERITY, new JsonArray().add(Severity.CRITICAL.name()).add(Severity.WARNING.name()).add(Severity.MAJOR.name()).add(Severity.CLEAR.name())));

        if (policy.containsKey(POLICY_SMS_NOTIFICATION_RECIPIENTS))
        {
            policy.remove(POLICY_SMS_NOTIFICATION_RECIPIENTS);
        }

        policy.remove(POLICY_MONITOR_POLLING_FAILED_NOTIFICATION_STATUS);

        policy.remove(POLICY_MONITOR_POLLING_FAILED_NOTIFICATION_TIMER_SECONDS);

        policy.put(POLICY_EMAIL_NOTIFICATION_SUBJECT, POLICY_EMAIL_NOTIFICATION_DEFAULT_SUBJECT).put(POLICY_MESSAGE, POLICY_EMAIL_NOTIFICATION_DEFAULT_MESSAGE).put(POLICY_NOTIFICATION_CONTEXT, notifyContext).put(POLICY_RENOTIFICATION_CONTEXT, renotifyContext);

        return policy;
    }
}

